const NAV_RULES={"uk":{"n":"United Kingdom","exp":{"law":"Export Control Act 2002; Export of Objects of Cultural Interest (Control) Order 2003 (SI 2003/2759); assimilated Regulation (EC) 116/2009 for exports from Northern Ireland. Thresholds unchanged since 2002.","authority":"Export Licensing Unit (ELU), Arts Council England, on behalf of the Secretary of State (DCMS). Applications digital, by e-mail; a new online portal has been in development since 2020.","fee":"The ACE guidance states no fee. Licences are understood to be free of charge (unconfirmed on an official page).","time":"Not referred: normally 5 business days (object legally imported within the last 50 years). Referred to an Expert Adviser: referral within 5 business days, adviser replies within 15; total normally 28 business days if no objection.","temporary":"Temporary licence normally for up to 3 years, one extension of up to 3 years; judged on fitness to travel, not national importance. Museums and regular fair exhibitors may hold an OIEL (up to 3 years). ATA carnet is a customs instrument, separate from the licence.","treasure":"Waverley criteria: history, aesthetics, scholarship; meeting one suffices. The Reviewing Committee (RCEWA) recommends a first deferral of 2–4 months for a serious expression of interest at fair market price, then a second deferral, usually up to 6 months, to complete the sale. Latest year: 5,745 applications, 28,000+ objects, 6 items saved (c. £500,000).","eu_licence":"Not needed from Great Britain. Northern Ireland: a UK licence for NI to EU; an EU licence (issued by ACE) for NI direct to non-EU countries. UK licences issued before 1 Jan 2021 are not valid for EU exports.","vf":"V","src":[["ACE Guidance for exporters, Issue 2 (2021)","https://www.artscouncil.org.uk/sites/default/files/download-file/Guidance_for_exporters_Issue_2_2021_0.pdf"],["ACE UK OGEL value limits","https://www.artscouncil.org.uk/sites/default/files/download-file/UK%20OGEL%20Value%20limits.pdf"],["gov.uk export licence for cultural goods","https://www.gov.uk/export-licence-for-cultural-goods"],["ACE export licensing page","https://www.artscouncil.org.uk/export-controls/export-licensing"],["The Art Newspaper, Herman, 14 Oct 2025","https://www.theartnewspaper.com/2025/10/14/comment-|-why-its-time-to-increase-uks-art-export-threshold"]],"none":false,"needs":[{"cat":"painting","age":50,"value":180000.0,"cur":"gbp","note":"Oil or tempera, excluding portraits of British historical personages (those: £10,000)."},{"cat":"sculpture","age":50,"value":65000.0,"cur":"gbp","note":"No separate line; falls under ‘any other article over 50 years’."},{"cat":"paper","age":50,"value":65000.0,"cur":"gbp","note":"Under ‘any other article’. Hand-produced architectural, scientific or engineering drawings: £0. Under ‘any other article’.","lowest":true},{"cat":"photo","age":50,"value":10000.0,"cur":"gbp","note":"Photographic positives, negatives or assemblages."},{"cat":"design","age":50,"value":65000.0,"cur":"gbp","note":"Textiles £12,000; arms and armour £35,000; UK archaeological material, manuscripts, documents and archives £0. Objects under 50 years old need no licence."}]},"imp":{"duty":"No customs duty on works of art, collectors’ items and antiques (chapter 97 of the UK Global Tariff), whatever the origin (BADA; tariff itself not opened).","vat":"Import VAT charged at 20% on a reduced valuation, giving an effective 5% (VAT Act 1994 s.21(4)); applies to works of art, collectors’ items and antiques over 100 years (headings 97.01–97.06). Standard 20% otherwise.","icg":"Regulation 2019/880 does not apply in Great Britain. It applies in Northern Ireland under the Windsor Framework (ACE page seen in search, not opened).","special":"Temporary Admission: import VAT suspended against security equal to the 5% VAT or a Customs Comprehensive Guarantee (waiver possible for dealers with a clean record). Chapter 97 commodity codes needed on the declaration; BADA members can issue a certificate of age.","vf":"V","vat_rate":0.05,"duty_rate":0,"src":[["HMRC Imports manual IMPS05200","https://www.gov.uk/hmrc-internal-manuals/imports/imps05200"],["BADA, importing from the EU and the rest of the world","https://www.bada.org/node/1785"]]},"aml":{"rule":"Money Laundering Regulations 2017 as amended by the 2019 Regulations (in force 10 Jan 2020): ‘art market participants’ who deal in sales, purchases and storage of works of art at or above the threshold (single or linked transactions, any payment method) must register with HMRC and apply customer due diligence (reg 27) on every such transaction. SI 2026/621 (made 9 June 2026, in force 21 days later) replaced the €10,000 threshold with £10,000 and extended enhanced due diligence to transactions that are unusually complex or unusually large (house research, Nov 2026).","threshold":"£10,000 since July 2026 (SI 2026/621); €10,000 from January 2020 to June 2026","asks":"Identity verification of the buyer, identification of any beneficial owner, and, on a risk basis, source of funds/wealth; records kept. Registration with HMRC (deadline originally 10 Jan 2021).","vf":"V","src":[["gov.uk policy paper, MLR amendment 2019","https://www.gov.uk/government/publications/money-laundering-and-terrorist-financing-amendment-regulations-2019/money-laundering-and-terrorist-financing-amendment-regulations-2019"],["SI 2026/621 (legislation.gov.uk)","https://www.legislation.gov.uk/uksi/2026/621/made"],["HMRC AMLG2100","https://www.gov.uk/hmrc-internal-manuals/anti-money-laundering-guidance-for-supervised-businesses/amlg2100"]]},"sanctions":{"rule":"Russia (Sanctions) (EU Exit) Regulations 2019, Schedule 3A (luxury goods, inserted 14 Apr 2022, last amended 20 May 2026): para 21 covers ‘works of art, collectors’ pieces and antiques, meaning any thing which falls within chapter 97’ with no price threshold (other entries carry £250 and higher thresholds). Export, supply to or for use in Russia banned; since 15 Dec 2023 also brokering, financial services and technical assistance. No UK import ban specific to Russian-origin art found.","vf":"V","src":[["legislation.gov.uk Schedule 3A","https://www.legislation.gov.uk/uksi/2019/855/schedule/3A?view=plain"],["K&L Gates, EU and UK luxury goods sanctions, 8 Aug 2024","https://www.klgates.com/The-Impact-of-the-EU-and-UK-Russian-Sanctions-Regime-on-the-Luxury-Goods-Sector-8-8-2024"]]},"apost":{"hague":true,"docs":"Documents certified by a UK notary or solicitor (powers of attorney, contracts, certified passport copies), court documents with a wet-ink seal, government documents. In an art sale: a notarised provenance affidavit, a notarised bill of sale or authenticity statement for a foreign court or customs; export licences are not usually apostilled.","authority":"FCDO Legalisation Office (get-document-legalised.service.gov.uk).","fee":"£45 standard; £35 e-Apostille; £40 Next-Day (registered businesses); £100 Restricted Urgent (businesses, pre-approved). Plus courier/postage.","time":"Standard up to 25 working days; e-Apostille up to 2 working days; Next-Day next working day; Restricted Urgent same day.","vf":"V","src":[["gov.uk Get your document legalised","https://www.gov.uk/get-document-legalised"]]},"cites":{"rule":"Ivory Act 2018 bans dealing (sale, hire, import/export for sale) in elephant ivory; extended 28 Jan 2025 to hippopotamus, killer whale, narwhal and sperm whale (walrus under separate rules). Exemptions: pre-1918 outstanding items (certificate £250, c. 3 months); pre-1947 items under 10% ivory, pre-1975 instruments under 20%, pre-1918 portrait miniatures (registration £20); museum sales. Max fine £250,000 or 5 years. CITES permits (tortoiseshell, rosewood, coral) via APHA: unconfirmed.","vf":"V","src":[["gov.uk Declare ivory you intend to sell or hire out (updated 24 Jul 2026)","https://www.gov.uk/guidance/declare-ivory-you-intend-to-sell-or-hire-out"]]}},"fr":{"n":"France","exp":{"law":"Code du patrimoine, art. L111-1 ff. and R111-1 ff. with Annexe 1 (categories, age and value thresholds); Décret n° 2020-1718 of 28 Dec 2020 raised 11 thresholds from 1 Jan 2021.","authority":"Ministère de la Culture, Direction générale des patrimoines et de l’architecture / service des musées de France (export certificates and AST).","fee":"Not stated on the pages opened; understood to be free (unconfirmed).","time":"Statutory 4-month decision period (unconfirmed, unconfirmed). Certificate granted automatically to goods imported into France less than 50 years ago; validity unlimited for works over 100 years, 20 years for works aged 50–100 years.","temporary":"Autorisation de sortie temporaire (AST) for exhibitions, expertise, restoration or deposit in a foreign public collection; AST TN for trésors nationaux (return compulsory). Duration not confirmed. The 2-year re-export window after temporary admission from outside the EU was extended by the 2020 decree.","treasure":"Refusal of the certificate classifies the work as a trésor national. Within 30 months of refusal the State may make a purchase offer; if the owner declines, experts fix the price; if the State waives acquisition, the work may leave. Advice from the Commission consultative des trésors nationaux.","eu_licence":"An EU licence (Reg 116/2009) is also needed to leave the EU customs territory, ‘désormais nécessaire pour les sorties vers le Royaume-Uni’; EU thresholds unchanged. Archaeology categories 1B/1C exempt from both.","vf":"V","src":[["Ministère de la Culture, note on certificates and AST, 13 Jan 2021","https://www.culture.gouv.fr/Media/Medias-creation-rapide/Certificats-et-AST_modifs-decret-seuils_13-01-2021.pdf"],["Ministère de la Culture, circulation des biens culturels","https://www.culture.gouv.fr/thematiques/musees/pour-les-professionnels/conserver-et-gerer-les-collections/gerer-les-collections/circulation-des-biens-culturels-et-marche-de-l-art"]],"none":false,"needs":[{"cat":"painting","age":50,"value":300000.0,"cur":"eur","note":"Was €150,000 before 2021."},{"cat":"sculpture","age":50,"value":100000.0,"cur":"eur","note":"Statuary and sculpture; was €50,000."},{"cat":"paper","age":50,"value":20000.0,"cur":"eur","note":"Drawings €30,000 (was €15,000); watercolours, gouaches, pastels €50,000 (was €30,000). Prints and posters; was €15,000.","lowest":true},{"cat":"photo","age":50,"value":25000.0,"cur":"eur","note":"Photographs, films, negatives; was €15,000."},{"cat":"design","age":50,"value":100000.0,"cur":"eur","note":"Other antiquities over 50 years (was €50,000). Archaeology from excavations over 100 years: €0; other archaeology and pre-1500 coins €3,000; post-1500 coins €15,000."}]},"imp":{"duty":"0% (EU common customs tariff, chapter 97; seen for 9705 on a TARIC mirror).","vat":"5.5% on imports and intra-EU acquisitions of works of art, collectors’ items and antiques (CGI art. 278-0 bis I and 278-0 B). Since 1 Jan 2025 all supplies of works of art are also at 5.5% (loi de finances 2024, art. 83); the dealer’s margin-scheme option (art. 297 B) was repealed from 1 Jan 2025. BOFiP text of 14 May 2025 was a consultation draft.","icg":"Regulation 2019/880 applies in full since 28 June 2025 (licence/statement via the ICG system).","special":"None found beyond the general EU customs procedures (temporary admission, customs warehousing).","vf":"V","vat_rate":0.055,"duty_rate":0,"src":[["BOFiP BOI-TVA-SECT-90-40 (14 May 2025)","https://bofip.impots.gouv.fr/bofip/1285-PGP.html/identifiant=BOI-TVA-SECT-90-40-20250514"],["TARIC 9705 10 00 mirror (duty 0%)","https://www.thetradehub.eu/en/customs/taric/97051000"]]},"aml":{"rule":"AMLD5 transposed: art dealers and intermediaries (and freeport operators) are obliged entities for transactions of €10,000 or more (Code monétaire et financier, not opened). From 10 July 2027 Regulation (EU) 2024/1624 applies directly (see EU).","threshold":"€10,000","asks":"ID, beneficial owner, source of funds on a risk basis (generic; French guidance not opened).","vf":"U","src":[["NRW tax administration note on EU AML Regulation obliged entities","https://www.finanzverwaltung.nrw.de/system/files/media/document/file/eu-aml-vo-erstinfo-verpflichtete_kunsthaendler-kunst-lagerhalter-kunstvermittler.pdf"]]},"sanctions":{"rule":"EU Regulation 833/2014 applies directly (Art 3h luxury goods incl. art over €300 per item; Art 5b deposits over €100,000). See EU entry.","vf":"S","src":[["K&L Gates, 8 Aug 2024","https://www.klgates.com/The-Impact-of-the-EU-and-UK-Russian-Sanctions-Regime-on-the-Luxury-Goods-Sector-8-8-2024"]]},"apost":{"hague":true,"docs":"Actes publics: notarial acts, court decisions, civil-status records, criminal-record extracts. For art: a notarised provenance declaration or power of attorney for use abroad.","authority":"Since 1 May 2025 the notariat (apostille.notaires.fr or the 15 regional notary councils) issues apostilles; legalisations moved to notaries on 1 Sept 2025 (décret n° 2021-1205; arrêté of 10 Apr 2025). Previously the parquets généraux of the 33 cours d’appel.","fee":"Individuals €10 HT per act (first three), €5 from the fourth; legal entities €20/€10; 24-hour express €20 (page footnotes conflict).","time":"No standard time stated; 24-hour express option.","vf":"S","src":[["Barreau de Paris, L’apostille: ce qui change (updated 2 Jul 2025)","https://www.avocatparis.org/actualites/lapostille-ce-qui-change"]]},"cites":{"rule":"EU regime applies (Reg 338/97; ivory rules in force 19 Jan 2022: no commercial import/export permits, intra-EU sale of worked ivory only with a certificate proving pre-1947 manufacture). See EU entry.","vf":"S","src":[["BADA on EU ivory rules from 19 Jan 2022","https://www.bada.org/resources/eu-commissions-recommendation-ivory-importexport-prohibition-starts-19-january-2022"]]}},"de":{"n":"Germany","exp":{"law":"Kulturgutschutzgesetz (KGSG) of 31 July 2016, § 24: exports to third countries need a licence under Reg 116/2009; exports to other EU states need a licence above national age and value thresholds (not for works owned by their creator).","authority":"Oberste Landesbehörde für Kultur of the Land where the object is located when the application is filed (§ 24(6)).","fee":"Set by Land law; not stated in § 24 (unconfirmed).","time":"Decision within 10 working days of a complete application (§ 24(7)). Value = price paid within the last 3 years, otherwise a reasoned domestic estimate (§ 24(4)).","temporary":"Objects proven to be in Germany only temporarily (up to 2 years) are exempt from the intra-EU licence (§ 24(8)); temporary export licences and general open licences for museums under § 22 (not opened).","treasure":"‘National wertvolles Kulturgut’ entered in a Land register (§§ 7–14 KGSG) may not be exported without permission; licence must be granted if no export ban under § 21 applies (§ 24(5)). Register mechanism not opened.","eu_licence":"Needed for any export to a non-EU country (§ 24(1) Nr 1 refers to Reg 116/2009); national thresholds only govern intra-EU movements.","vf":"V","src":[["§ 24 KGSG, gesetze-im-internet.de","https://www.gesetze-im-internet.de/kgsg/__24.html"]],"none":false,"needs":[{"cat":"painting","age":75,"value":300000.0,"cur":"eur","note":"Intra-EU threshold (§ 24(2) Nr 3). To third countries: Reg 116/2009 (50 years, €150,000)."},{"cat":"sculpture","age":75,"value":100000.0,"cur":"eur","note":"Nr 7. Third countries: €50,000."},{"cat":"paper","age":75,"value":50000.0,"cur":"eur","note":"Drawings and mosaics (Nr 5) €50,000; watercolours, gouaches, pastels (Nr 4) €100,000. Nr 6.","lowest":true},{"cat":"photo","age":75,"value":50000.0,"cur":"eur","note":"Nr 8."},{"cat":"design","age":100,"value":100000.0,"cur":"eur","note":"Nr 15 other antiques 100 years/€100,000; archives Nr 12 50 years/€50,000; means of transport 150 years/€100,000; otherwise Reg 116/2009 ages with double the EU values."}]},"imp":{"duty":"0% (EU chapter 97).","vat":"7% on imports, intra-EU acquisitions and supplies of works of art (§ 12(2) Nr 1 UStG with Anlage 2 Nr 53). The Jahressteuergesetz 2024 restored the reduced rate for all supplies from 1 Jan 2025 and repealed § 12(2) Nr 12 and 13 UStG.","icg":"Regulation 2019/880 applies since 28 June 2025; German competent authority information at kunstverwaltung.bund.de (not opened).","special":"None found.","vf":"V","vat_rate":0.07,"duty_rate":0,"src":[["Bayerisches Landesamt für Steuern, Verfügung 14 Jan 2025 (S 7220.2.1-33/111)","https://lfst.bayern.de/fileadmin/RESSOURCEN/INFORMATIONEN/Steuerinfos/Steuerarten/Umsatzsteuer/S_7220.2.1-33_111_St33_vom_14.01.2025.pdf"]]},"aml":{"rule":"Geldwäschegesetz: Güterhändler, Kunstvermittler and Kunstlagerhalter are obliged entities from €10,000 (cash and non-cash). From 10 July 2027 Reg 2024/1624 Art 3(3)(i),(j) applies: traders and intermediaries in cultural goods (galleries, auction houses) and storers in free zones/customs warehouses, €10,000; ‘cultural goods’ follow Annex I of Reg 116/2009.","threshold":"€10,000","asks":"Identification of the customer and beneficial owner, purpose of the transaction, source of funds on a risk basis (NRW page does not detail).","vf":"V","src":[["NRW Finanzverwaltung, EU-AML-VO Erstinformation Kunsthändler","https://www.finanzverwaltung.nrw.de/system/files/media/document/file/eu-aml-vo-erstinfo-verpflichtete_kunsthaendler-kunst-lagerhalter-kunstvermittler.pdf"]]},"sanctions":{"rule":"EU Regulation 833/2014 applies directly. See EU entry.","vf":"S","src":[["K&L Gates, 8 Aug 2024","https://www.klgates.com/The-Impact-of-the-EU-and-UK-Russian-Sanctions-Regime-on-the-Luxury-Goods-Sector-8-8-2024"]]},"apost":{"hague":true,"docs":"Notarial deeds and court documents (apostilled by the Landgericht president of the district), administrative documents (Land interior authorities), federal documents (Bundesverwaltungsamt). Authorities vary by Land; the AA page names none.","authority":"Varies: Bundesverwaltungsamt for federal documents; Land justice and interior authorities otherwise (allocation unconfirmed).","fee":"Fee-based (‘gebührenpflichtige Amtshandlung’); amounts vary by Land, typically around €25 (unconfirmed).","time":"No fixed time; the Federal Foreign Office warns of long waits (‘lange Wartezeiten’).","vf":"U","src":[["Auswärtiges Amt FAQ on the Hague apostille","https://www.auswaertiges-amt.de/de/service/fragenkatalog-node/12-apostille-ausl-606196"]]},"cites":{"rule":"EU regime applies (Reg 338/97; ivory rules from 19 Jan 2022). See EU entry.","vf":"S","src":[["BADA on EU ivory rules","https://www.bada.org/resources/eu-commissions-recommendation-ivory-importexport-prohibition-starts-19-january-2022"]]}},"it":{"n":"Italy","exp":{"law":"Codice dei beni culturali e del paesaggio (D.Lgs. 42/2004), art. 65 and 68, as amended by L. 124/2017 and by Legge 17 marzo 2026 n. 40 (GU 30 Mar 2026): the value threshold for works by deceased authors made over 70 years ago rose from €13,500 to €50,000.","authority":"Uffici Esportazione of the Ministero della Cultura (Soprintendenze), via the SUE online portal (unconfirmed, unconfirmed).","fee":"No fee found; stamp duty on the application likely (unconfirmed).","time":"Decision period for the attestato (40 days in the Code, unconfirmed) not confirmed; L. 40/2026 sets 90 days for loan authorisations. The applicant may withdraw the request before the final decision. Self-declaration validity now aligned with the attestato’s duration (art. 65(4-ter)).","temporary":"Attestato di circolazione temporanea (art. 71) for exhibitions and fairs (not opened; unconfirmed).","treasure":"Dichiarazione dell’interesse culturale (notifica/vincolo, art. 13) makes a work inexportable; a temporary ban applies to works by deceased authors over 70 years until the verification under art. 12. Under L. 40/2026 the attestato cannot be refused to works by foreign authors unless specific relevance to Italian cultural history is established. Constitutional Court judgment 51/2026 on sub-€13,500 works not opened.","eu_licence":"EU licence (Reg 116/2009) also required for exports outside the EU above the EU thresholds (standard EU rule; Italian page not opened).","vf":"V","src":[["Art. 65 Codice dei beni culturali (Brocardi, consolidated with L. 40/2026)","https://brocardi.it/codice-dei-beni-culturali-e-del-paesaggio/parte-seconda/titolo-i/capo-v/sezione-i-bis/art65.html"],["Finestre sull’Arte on Law 40/2026","https://www.finestresullarte.info/en/policy/cultural-heritage-what-changes-the-recently-passed-law-has-made"]],"none":false,"needs":[{"cat":"painting","age":70,"value":50000.0,"cur":"eur","note":"Author deceased, made over 70 years ago, value above €50,000: attestato di libera circolazione (art. 68). Below €50,000 or under 70 years/living author: self-declaration (DPR 445/2000) to the Ufficio Esportazione."},{"cat":"sculpture","age":70,"value":50000.0,"cur":"eur","note":"Same rule."},{"cat":"paper","age":70,"value":50000.0,"cur":"eur","note":"Same rule. Same rule.","lowest":true},{"cat":"photo","age":70,"value":50000.0,"cur":"eur","note":"Same rule."},{"cat":"design","age":70,"value":50000.0,"cur":"eur","note":"Books and library goods keep the €13,500 threshold; private archives and documents of cultural interest and art. 11(1)(f),(g),(h) categories need authorisation at any value. Vincolati beni culturali (art. 10) may never leave definitively."}],"dead":true},"imp":{"duty":"0% (EU chapter 97).","vat":"5% on imports and sales of works of art, antiques and collectors’ items from 1 July 2025 (decreto-legge 30 June 2025 n. 95); previously 10% on imports and 22% on dealer sales (prior rates unconfirmed). Margin scheme restricted for goods bought or imported at 5%.","icg":"Regulation 2019/880 applies since 28 June 2025.","special":"None found.","vf":"S","vat_rate":0.05,"duty_rate":0,"src":[["Assolombarda, IVA 5% dal 1 luglio 2025","https://www.assolombarda.it/servizi/fisco/informazioni/iva-dal-1deg-luglio-2025-scontano-l2019aliquota-del-5-le-importazioni-e-le-cessioni-di-oggetti-d2019arte-di-antiquariato-o-da-collezione"]]},"aml":{"rule":"AMLD5 transposed (D.Lgs. 231/2007 as amended by D.Lgs. 125/2019): art dealers, intermediaries and freeport operators obliged from €10,000 (not opened). Reg 2024/1624 applies from 10 July 2027.","threshold":"€10,000","asks":"ID, beneficial owner, source of funds (generic).","vf":"U","src":[["NRW note on Reg 2024/1624","https://www.finanzverwaltung.nrw.de/system/files/media/document/file/eu-aml-vo-erstinfo-verpflichtete_kunsthaendler-kunst-lagerhalter-kunstvermittler.pdf"]]},"sanctions":{"rule":"EU Regulation 833/2014 applies directly. See EU entry.","vf":"S","src":[["K&L Gates, 8 Aug 2024","https://www.klgates.com/The-Impact-of-the-EU-and-UK-Russian-Sanctions-Regime-on-the-Luxury-Goods-Sector-8-8-2024"]]},"apost":{"hague":true,"docs":"Notarial and judicial documents via the Procura della Repubblica; administrative documents via the Prefettura (unconfirmed).","authority":"Procura della Repubblica / Prefettura (unconfirmed).","fee":"Marca da bollo €16 per apostille (unconfirmed).","time":"Unconfirmed.","vf":"U","src":[]},"cites":{"rule":"EU regime applies. See EU entry.","vf":"S","src":[["BADA on EU ivory rules","https://www.bada.org/resources/eu-commissions-recommendation-ivory-importexport-prohibition-starts-19-january-2022"]]}},"nl":{"n":"Netherlands","exp":{"law":"Erfgoedwet (Heritage Act, in force 1 July 2016), art. 4.23: protected cultural goods (beschermde cultuurgoederen, listed in the register) may not leave the Netherlands without permission; Reg 116/2009 for exports outside the EU.","authority":"Inspectie Overheidsinformatie en Erfgoed, in cooperation with the Belastingdienst/Douane; apply to Customs for an ‘uitvoervergunning cultuurgoederen’. Export by post or courier not permitted.","fee":"Not stated (unconfirmed).","time":"Not stated (unconfirmed).","temporary":"Temporary export licences exist under the EU regulation; Dutch details not opened.","treasure":"Register of protected cultural goods under the Erfgoedwet; export of listed objects requires ministerial permission (government.nl refers to art. 4.23 Erfgoedwet).","eu_licence":"Needed for exports outside the EU above the Reg 116/2009 thresholds.","vf":"V","src":[["government.nl, applying for an export licence for cultural goods","https://www.government.nl/topics/art-and-culture/applying-for-an-export-licence-for-cultural-goods"]],"none":true,"needs":[],"listed":"Objects in the register of protected cultural goods need the minister’s permission for any destination."},"imp":{"duty":"0% (EU chapter 97).","vat":"9% reduced rate retained for culture, media and sport from 1 Jan 2026 (Wet van 29 Oct 2025, Stb. 2025, 339, reversing the planned rise to 21%; only accommodation goes to 21%). Imports of works of art fall under the 9% rate (Tabel I; Dutch tax page not opened).","icg":"Regulation 2019/880 applies since 28 June 2025.","special":"None found.","vf":"S","vat_rate":0.09,"duty_rate":0,"src":[["NJB, Wet van 29-10-2025, Stb. 2025, 339","https://www.njb.nl/wetgeving/staatsbladen/behoud-verlaagd-btw-tarief-op-cultuur-media-en-sport/"]]},"aml":{"rule":"Wwft: art dealers and intermediaries obliged from €10,000 (AMLD5 transposition; not opened). Reg 2024/1624 applies from 10 July 2027.","threshold":"€10,000","asks":"ID, beneficial owner, source of funds (generic).","vf":"U","src":[["NRW note on Reg 2024/1624","https://www.finanzverwaltung.nrw.de/system/files/media/document/file/eu-aml-vo-erstinfo-verpflichtete_kunsthaendler-kunst-lagerhalter-kunstvermittler.pdf"]]},"sanctions":{"rule":"EU Regulation 833/2014 applies directly. See EU entry.","vf":"S","src":[["K&L Gates, 8 Aug 2024","https://www.klgates.com/The-Impact-of-the-EU-and-UK-Russian-Sanctions-Regime-on-the-Luxury-Goods-Sector-8-8-2024"]]},"apost":{"hague":true,"docs":"Notarial and court documents apostilled by the rechtbank (district court); fee about €25 (unconfirmed).","authority":"Rechtbanken (unconfirmed).","fee":"Unconfirmed.","time":"Unconfirmed.","vf":"U","src":[]},"cites":{"rule":"EU regime applies. See EU entry.","vf":"S","src":[["BADA on EU ivory rules","https://www.bada.org/resources/eu-commissions-recommendation-ivory-importexport-prohibition-starts-19-january-2022"]]}},"es":{"n":"Spain","exp":{"law":"Ley 16/1985 del Patrimonio Histórico Español (arts. 5, 29–33) and Real Decreto 111/1986 (arts. 45–51): export permit for goods over 100 years old and goods in the Inventario General; BIC inexportable (art. 5 not opened).","authority":"Ministerio de Cultura (Dirección General de Bellas Artes), or the Comunidad Autónoma where it has taken over processing, after the opinion of the Junta de Calificación, Valoración y Exportación (RD 111/1986 arts. 47–48).","fee":"Export tax (art. 30 LPHE) on definitive exports: 5% up to 1,000,000 pesetas; 10% to 10,000,000; 20% to 100,000,000; 30% above (euro equivalents c. €6,010 / €60,101 / €601,012, own conversion). Exempt: goods imported within 10 years, temporary exports, works by living authors.","time":"Decision within 3 months of receipt; silence may be taken as approval, with a certification issued within 20 days of request (RD 111/1986 art. 49).","temporary":"Temporary export permit (art. 31): the authorisation fixes the term and guarantees; not subject to the State’s pre-emptive purchase; failure to return is treated as illegal export.","treasure":"The declared value in a definitive export request is an irrevocable offer of sale to the State; on refusal the State has 6 months to accept and 1 year to pay (art. 33 LPHE; RD art. 50). The Ministry may declare an item inexportable as a precaution while a protection file is opened (RD art. 51).","eu_licence":"Needed for exports outside the EU above the Reg 116/2009 thresholds, in addition to the national permit.","vf":"S","src":[["Ley 16/1985, Título III (normatia, 2026 consolidated)","https://normatia.com/es/normativa/patrimonio-historico-espanol/2026/titulo-iii-de-los-bienes-muebles/"],["RD 111/1986, permiso de exportación (papelea)","https://papelea.com/es/leyes/real-decreto-111-1986/titulo-iii_capitulo-ii_seccion-1-permiso-de-exportacion"]],"none":false,"needs":[{"cat":"any","age":100,"value":0,"note":"any work over 100 years old, or in the General Inventory, whatever the value; a definitive export pays the export tax (5% to 30% of the value by band); works by living authors are exempt from the tax; goods imported within the last 10 years leave without pre-emption"}],"tax":"export tax on definitive exports: 5% up to about €6,010, 10% to about €60,101, 20% to about €601,012, 30% above (the peseta bands of 1985, converted)"},"imp":{"duty":"0% (EU chapter 97).","vat":"10% on imports of works of art, antiques and collectors’ items whoever the importer (art. 91.Uno.4 Ley 37/1992); 10% on sales by the artist or heirs; 21% general rate otherwise; dealers use the margin scheme (REBU, arts. 135–139). Spain had not transposed Directive 2022/542 as of Feb 2026.","icg":"Regulation 2019/880 applies since 28 June 2025.","special":"None found.","vf":"S","vat_rate":0.1,"duty_rate":0,"src":[["Cuatrecasas, El tipo impositivo del IVA en el mercado del arte español (6 Feb 2026)","https://www.cuatrecasas.com/es/spain/fiscalidad/art/iva-mercado-arte-espanol"]]},"aml":{"rule":"Ley 10/2010: art dealers and intermediaries obliged from €10,000 (AMLD5 transposition; not opened). Reg 2024/1624 applies from 10 July 2027.","threshold":"€10,000","asks":"ID, beneficial owner, source of funds (generic).","vf":"U","src":[["NRW note on Reg 2024/1624","https://www.finanzverwaltung.nrw.de/system/files/media/document/file/eu-aml-vo-erstinfo-verpflichtete_kunsthaendler-kunst-lagerhalter-kunstvermittler.pdf"]]},"sanctions":{"rule":"EU Regulation 833/2014 applies directly. See EU entry.","vf":"S","src":[["K&L Gates, 8 Aug 2024","https://www.klgates.com/The-Impact-of-the-EU-and-UK-Russian-Sanctions-Regime-on-the-Luxury-Goods-Sector-8-8-2024"]]},"apost":{"hague":true,"docs":"Notarial documents apostilled by the Colegios Notariales; judicial and administrative documents by the Ministerio de Justicia (unconfirmed).","authority":"Ministerio de Justicia / Colegios Notariales (unconfirmed).","fee":"Unconfirmed.","time":"Unconfirmed.","vf":"U","src":[]},"cites":{"rule":"EU regime applies. See EU entry.","vf":"S","src":[["BADA on EU ivory rules","https://www.bada.org/resources/eu-commissions-recommendation-ivory-importexport-prohibition-starts-19-january-2022"]]}},"ch":{"n":"Switzerland","exp":{"law":"Bundesgesetz über den internationalen Kulturgütertransfer (KGTG, SR 444.1, in force 1 June 2005) and Verordnung KGTV (SR 444.11); customs directive BAZG R-60-2.7 (valid from 1 Jan 2026). No general export licence.","authority":"Bundesamt für Kultur (BAK), Fachstelle Internationaler Kulturgütertransfer, for register objects; cantons for cantonal registers; BAZG (customs) for declarations.","fee":"None found.","time":"None found.","temporary":"Temporary admission (ZAVV declaration or ATA carnet) for exhibitions, sales exhibitions and auctions; durations not stated on the page.","treasure":"Federal register (Bundesverzeichnis) of federal cultural property: permanent export prohibited; cantonal registers under cantonal law. Unlawful export only where the good was imported in breach of a bilateral agreement (Art. 7 KGTG) or is a listed state object (Art. 24(1)(d)).","eu_licence":"Not applicable (non-EU). Entering the EU, Swiss-held works need a Reg 2019/880 licence or statement; Switzerland is relevant for works held there over 5 years when the country of origin cannot be reliably determined.","vf":"V","src":[["BAZG R-60-2.7 Kulturgütertransfer (valid 1 Jan 2026)","https://www.bazg.admin.ch/dam/de/sd-web/vuDkj5myCXVU/R-60-2.7_Kulturguetertransfer.pdf"],["BAK, Informationen und FAQ zum Kunsthandel und Auktionswesen","https://www.bak.admin.ch/dam/bak/de/dokumente/kulturguetertransfer/publikationen/informationen-und-faq-zum-kunsthandel-und-auktionswesen.pdf.download.pdf/Informationen%20und%20FAQ%20zum%20Kunsthandel%20und%20Auktionswesen.pdf"],["Borel & Barbey art law newsletter, Sept 2025","https://www.borel-barbey.ch/wp-content/uploads/2025/09/BB-NL_ArtLaw_092025.pdf"]],"none":true,"needs":[],"listed":"Objects in the federal register may not leave permanently; every cultural good is declared at export with its type, origin, date and size."},"imp":{"duty":"Works of art for long-term public display may be imported duty-free on an undertaking not to sell (form 11.32); artists’ own works duty-free. General abolition of industrial tariffs from 1 Jan 2024 (not opened). Handcrafts are not works of art.","vat":"Import VAT at the standard rate of 8.1% (since 1 Jan 2024); no reduced rate for art (rate page not opened). Dealers may use the VAT transfer procedure (Verlagerungsverfahren) for art imports (unconfirmed).","icg":"Not applicable; the BAK fact sheet (11 Jul 2025) explains the EU rules for goods leaving Switzerland.","special":"Imports from states with a bilateral agreement (Art. 7 KGTG) need proof of lawful export recorded in the declaration. Storage in a customs warehouse counts as an import under the KGTG: written notice to BAZG on form 11.95 in duplicate.","vf":"S","vat_rate":0.081,"duty_rate":0,"src":[["BAZG, works of art and exhibition objects","https://www.bazg.admin.ch/en/works-of-art-and-exhibition-objects"],["BAZG R-60-2.7","https://www.bazg.admin.ch/dam/de/sd-web/vuDkj5myCXVU/R-60-2.7_Kulturguetertransfer.pdf"],["BAK fact sheet on EU Reg 2019/880 (11 Jul 2025)","https://www.bak.admin.ch/dam/bak/en/dokumente/kulturguetertransfer/merkblatt_hinweis/Faktenblatt%20EU%20Einfuhrverordnung%2020197-880-stand%2011.07.2025.pdf.download.pdf/Faktenblatt%20EU%20Einfuhrverordnung%2020197-880-stand%2011.07.2025.pdf"]]},"aml":{"rule":"Art dealers are not financial intermediaries under the AMLA; cash sales above CHF 100,000 trigger AML duties for traders (unconfirmed). KGTG Art. 16 due diligence: identify the seller (name, date of birth, address, nationality), obtain a written declaration of the right to dispose, inform clients of import/export rules, keep records 30 years; exempt below CHF 5,000 except archaeology, palaeontology, ethnology and monument fragments.","threshold":"CHF 5,000 (KGTG due diligence); CHF 100,000 cash (AMLA, unconfirmed)","asks":"Seller identity and written declaration of right to dispose; buyer identity for cash above CHF 100,000.","vf":"V","src":[["BAK, Informationen und FAQ zum Kunsthandel und Auktionswesen","https://www.bak.admin.ch/dam/bak/de/dokumente/kulturguetertransfer/publikationen/informationen-und-faq-zum-kunsthandel-und-auktionswesen.pdf.download.pdf/Informationen%20und%20FAQ%20zum%20Kunsthandel%20und%20Auktionswesen.pdf"]]},"sanctions":{"rule":"Switzerland has aligned with the EU luxury goods ban (Ordinance on measures in connection with the situation in Ukraine), including works of art over CHF 300 per item (unconfirmed; SECO page not opened).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Cantonal documents (notarial deeds, court documents) apostilled by the cantonal chancellery; federal documents by the Federal Chancellery (unconfirmed).","authority":"Cantonal Staatskanzlei / Federal Chancellery (unconfirmed).","fee":"Unconfirmed.","time":"Unconfirmed.","vf":"U","src":[]},"cites":{"rule":"Swiss CITES rules (Federal Act on Trade in Protected Species) apply; ivory and other Annex A items need permits; not opened.","vf":"U","src":[]},"freeport":{"rule":"Geneva Ports Francs: Swiss Federal Audit Office found 245 open customs warehouses (2012) and 10 free ports (2013, down from 18 in 2008); goods in 201 warehouses over CHF 15bn, suspended duties over CHF 1bn; press figure of CHF 100bn in Geneva unverified; 841 free-port controls in 2012; 8 recommendations. Storage counts as import under the KGTG (form 11.95; stock-record entry compulsory). 2016 inventory rules, storage fees and the new customs law not confirmed.","vf":"V","src":[["EFK/CDF audit summary of customs warehouses and free ports","https://efk.admin.ch/wp-content/uploads/publikationen/berichte/wirtschaft_und_verwaltung/oeffentliche_finanzen_und_steuern/12490/12490zf_f.pdf"],["BAZG R-60-2.7","https://www.bazg.admin.ch/dam/de/sd-web/vuDkj5myCXVU/R-60-2.7_Kulturguetertransfer.pdf"]]}},"us":{"n":"United States","exp":{"law":"No export licence for works of art as such. Export rules touch art only through CITES/ESA (ivory, tortoiseshell), OFAC sanctions programmes and the EAR luxury-goods rule for Russia and Belarus (15 CFR 746 Supp. 5). No federal cultural-property export control exists.","authority":"None for art. US Fish and Wildlife Service for ESA/CITES species; BIS and OFAC for sanctions.","fee":"n/a","time":"n/a","temporary":"The US accepts ATA carnets (issued in the US by the US Council for International Business); works brought in on temporary entry that sell at a US fair become dutiable on re-import (Cultural Property News, Nov 2025).","vf":"S","note":"Carnet acceptance carried unconfirmed (U); no official CBP carnet page opened.","src":[["Cultural Property News, The New Costs of Collecting, 7 Nov 2025","https://culturalpropertynews.org/the-new-costs-of-collecting-how-2025-tariffs-are-reshaping-the-art-and-antiques-trade/"],["FWS, What can I do with my ivory","https://www.fws.gov/carp/sites/default/files/documents/What%20Can%20I%20Do%20With%20My%20Ivory_%20%281%29.pdf"]],"none":true,"needsText":"Nothing for a painting, sculpture or work on paper beyond the shipper’s routine export declaration. An FWS declaration is needed if the object contains CITES-listed material. Nothing opened this session states the negative on an official page; the absence is inferred from the sources read.","needs":[]},"imp":{"duty":"HTSUS chapter 97 (9701 paintings, 9702 original prints, 9703 sculpture, 9705 collectors’ pieces, 9706 antiques over 100 years) is ‘Free’ at the MFN rate in the 2026 schedule.","vat":"No federal VAT. State sales or use tax attaches where the work is delivered or first used.","state_tax":"New York: use tax (NYC 8.875%) on art bought elsewhere and used in NY, but property bought while a non-resident is exempt (Tax Law §1118(2); TSB-A-08(7)S, 14 Feb 2008); carrying on business in NY makes one a resident. Delaware has no sales tax. California and Florida use-tax rules, and NY’s 2017 six-month amendment, were not opened this session (U).","overlays":"IEEPA ‘reciprocal’ and fentanyl tariffs were struck down by the Supreme Court on 20 Feb 2026 (Learning Resources v. Trump); art had anyway been treated as exempt ‘informational materials’ (50 USC 1702(b)(3)). A s.122 surcharge (10%, then 15%) ran 24 Feb–24 Jul 2026 with the same exemption. The s.301 forced-labour tariffs from 24 Jul 2026 (10–12.5%, c.60–80 economies) exclude all of chapter 97 (HTSUS 9903.05.86; 91 FR 47318).","overlays_note":"Chinese-origin art still bears the 7.5% s.301 List 4A duty (15% from Sept 2019, halved in 2020; The Art Newspaper, Dec 2023; not re-checked on USTR this session). Canadian-origin art is reported to fall under separate 2026 Canada tariffs (The Art Newspaper, 28 Jul 2026; rate unconfirmed). IEEPA refunds run through CBP’s CAPE process (c.$165bn). The $800 de minimis exemption is gone, so every shipment is formally entered.","cpia":"Under the Convention on Cultural Property Implementation Act the US restricts import of archaeological/ethnological material from 32 countries (State Dept Cultural Heritage Center list, archived to May 2025) plus Nepal from 12 Aug 2026 (CBP Dec. 26-16, to 8 Jan 2031); modern paintings and sculpture are not covered.","vf":"S","note":"Tariff overlays rest on trade press and law-firm notes that cite the Federal Register (91 FR 47318, 28 Jul 2026); the FR notice itself was not opened. CPIA list and Nepal rule read on official pages (V).","vat_rate":0,"duty_rate":0,"src":[["ustariffrates.com, chapter 97 (2026 rates)","https://www.ustariffrates.com/chapter/art"],["DLA Piper, Supreme Court holds IEEPA does not authorise tariffs, 24 Feb 2026","https://www.dlapiper.com/insights/publications/2026/02/us-supreme-court-holds-ieepa-does-not-authorize-tariffs"],["Sullivan & Worcester via JD Supra, art after the IEEPA decision, 4 Mar 2026","https://www.jdsupra.com/legalnews/art-and-collectibles-markets-aided-by-3181248/"],["Strix, s.122 surcharge ended 24 Jul 2026","https://www.strixsmart.com/section-122-surcharge"],["The Art Newspaper, new tariffs largely exempt art and antiques, 28 Jul 2026","https://www.theartnewspaper.com/2026/07/28/new-trump-tariffs-largely-exempt-art-antiques"],["Cultural Property News, chapter 97 excluded from the 2026 s.301 action (91 FR 47318), 4 Aug 2026","https://culturalpropertynews.org/?p=16913"],["The Art Newspaper, tariffs on art and China–US relations, 26 Dec 2023","https://www.theartnewspaper.com/2023/12/26/tariffs-on-art-are-worsening-frayed-china-us-relations-deepening-ongoing-trade-war"],["Artnet, what the US–China deal means for art tariffs","https://news.artnet.com/art-world-archives/what-does-us-china-trade-deal-mean-for-art-tariffs-1732263?amp=1"],["NY Dept of Taxation and Finance, TSB-A-08(7)S","https://www.tax.ny.gov/pdf/advisory_opinions/sales/a08_7s.pdf"],["Artnet, Delaware Freeport, 16 Oct 2015 (NYC 8.875%)","https://news.artnet.com/market/delaware-freeport-tax-haven-341366"],["State Dept ECA (archive 2012–2025), current agreements and import restrictions","https://2012-2025.eca.state.gov/cultural-heritage-center/cultural-property/current-agreements-and-import-restrictions.html"],["Federal Register public inspection, CBP Dec. 26-16, Nepal import restrictions, 12 Aug 2026","https://public-inspection.federalregister.gov/2026-16432.pdf"]]},"aml":{"rule":"Art dealers and auction houses are not BSA ‘financial institutions’. The AML Act 2020 added antiquities dealers and ordered a Treasury study of art (no rule for either). The Art Market Integrity Act (Grassley, Whitehouse, Fetterman, Cassidy, Kim, McCormick; announced 23–29 Jul 2025) would add ‘a person engaged in the trade in works of art’ with full BSA duties. As of 3 Nov 2026 no enactment or FinCEN art rule was found.","threshold":"Bill: exempt if no single art transaction above $10,000 or under $50,000 of art transactions in the prior year; artists selling their own work exempt. Current law: cash over $10,000 is reported on Form 8300 by any trade (U).","asks":"Houses ask for government ID, proof of address, a beneficial-owner declaration and, above internal thresholds, source-of-funds and source-of-wealth papers; the 2020 PSI report found all four houses treated the agent as principal and did not ask for whom he bought, which they have since changed (practice, not opened on a house page this session).","vf":"S","note":"Bill status after Aug 2025 not found in a 2026 source; treated as pending. House KYC practice is U.","src":[["DLA Piper, Art Market Integrity Act introduced, 21 Aug 2025","https://www.dlapiper.com/en-us/insights/publications/2025/08/art-market-integrity-act-introduced-with-bipartisan-support"],["Sen. Whitehouse press release, 29 Jul 2025","https://www.whitehouse.senate.gov/news/release/whitehouse-colleagues-introduce-bipartisan-legislation-to-crack-down-on-money-laundering-and-terror-financing-in-the-art-market"],["Senate PSI staff report, The Art Industry and U.S. Policies that Undermine Sanctions, 29 Jul 2020","https://www.hsgac.senate.gov/wp-content/uploads/imo/media/doc/2020-07-29%20PSI%20Staff%20Report%20-%20The%20Art%20Industry%20and%20U.S.%20Policies%20that%20Undermine%20Sanctions.pdf"]]},"sanctions":{"rule":"OFAC SDN screening and the 50% rule apply to every sale. EAR 15 CFR 746 Supp. 5 (per §746.8(a)(7); §746.10 is now reserved): paintings, prints, sculpture, collectors’ pieces and antiques with a US wholesale value of $300 or more per unit are ‘luxury goods’ barred for export or re-export to Russia or Belarus, and to listed oligarchs wherever located. No US ban on importing Russian-origin art was found; EO 14068’s import bans cover fish, seafood, alcohol and diamonds (U).","detail":"FinCEN alert of 16 Mar 2022 (number FIN-2022-Alert003 not shown on the page opened) names artworks among high-value assets used to evade Russia sanctions and lists red flags (shell companies, parties linked to sanctioned Russians, art-insurance changes). Senate PSI report of 29 Jul 2020 traced over $18m of 2014 art purchases to Rotenberg-linked shell companies via Christie’s, Sotheby’s and private sales after their 20 Mar 2014 designation.","vf":"S","note":"Supplement 5 read on a CFR mirror, not ecfr.gov (refused). EO 14068 import-ban list unconfirmed.","src":[["15 CFR 746 Supplement No. 5 (regulation mirror, checked 3 Nov 2026)","https://www.customsmobile.com/regulations/title15_chapterVII-i1_part746_appendix-i4"],["15 CFR part 746 contents (mirror; §746.10 reserved)","https://www.customsmobile.com/regulations/title15_chapterVII-i1_part746"],["Covington, FinCEN alert on evasion of Russia sanctions, 17 Mar 2022","https://www.cov.com/en/news-and-insights/insights/2022/03/fincens-alert-on-aml-risk-from-evasion-of-russia-sanctions"],["Senate PSI staff report, 29 Jul 2020","https://www.hsgac.senate.gov/wp-content/uploads/imo/media/doc/2020-07-29%20PSI%20Staff%20Report%20-%20The%20Art%20Industry%20and%20U.S.%20Policies%20that%20Undermine%20Sanctions.pdf"]]},"apost":{"hague":true,"docs":"Notarised provenance affidavits, powers of attorney for a consignment and corporate certificates are apostilled by the Secretary of State of the state that commissioned the notary; only federal documents go to the State Department (split carried unconfirmed, U). Customs itself does not require apostilles.","authority":"Office of Authentications, US Department of State (600 19th St NW, Washington DC; Form DS-4194) for federal documents; state Secretaries of State for notarised documents. Party since 15 Oct 1981 (accession 24 Dec 1980).","fee":"$20 per document (federal office; non-refundable). State fees vary.","time":"Mail-in: up to 5 weeks from receipt. Walk-in: 7 business days (drop-off Mon–Thu 7:30–9:00). Same-day only for family emergencies abroad.","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"],["State Dept Office of Authentications, request services","https://adoption.state.gov/en/replace-certify/authenticate-documents/request-services.html"]]},"cites":{"rule":"FWS Division of Management Authority issues CITES permits; all wildlife imports/exports are declared to FWS Law Enforcement. African elephant ivory 4(d) rule in force 6 Jul 2016: commercial import banned; ESA antiques (100+ years, unmodified since 1973, entered via an antique port) may move with CITES papers; interstate sale only for ESA antiques or de minimis items (<200 g, <50% of value, pre-2016); raw ivory may not be exported. NY and CA laws are stricter (U).","vf":"V","src":[["FWS, What can I do with my ivory","https://www.fws.gov/carp/sites/default/files/documents/What%20Can%20I%20Do%20With%20My%20Ivory_%20%281%29.pdf"]]},"freeport":{"rule":"Delaware Freeport (Newark, DE; conceived by Fritz Dietl; opened Sept 2015; 36,000 sq ft) stores art in a state with no sales tax, two hours from New York, where a buyer would pay 8.875%. Chapter 97 is duty-free, so US bonded warehouses and the JFK/Newark foreign-trade zones matter for state use tax and deferral only; use tax attaches when the work enters the owner’s home state. ARCIS (Harlem) and NY bonded storage not opened (U). Fees not published.","vf":"S","src":[["Artnet, Delaware Freeport, 16 Oct 2015","https://news.artnet.com/market/delaware-freeport-tax-haven-341366"],["NY Dept of Taxation and Finance, TSB-A-08(7)S (art stored in Delaware)","https://www.tax.ny.gov/pdf/advisory_opinions/sales/a08_7s.pdf"]]}},"ae":{"n":"United Arab Emirates (Dubai and Abu Dhabi)","exp":{"law":"No export licence for works of art. Antiquities fall under Federal Law 11 of 2017 on antiquities and emirate heritage rules (Dubai Culture, Abu Dhabi DCT) — carried unconfirmed.","authority":"Federal Authority for Identity, Citizenship, Customs and Port Security; Dubai Customs; Abu Dhabi Customs. Abu Dhabi’s waiver committee must approve temporary export of works admitted under the duty-waiver programme.","fee":"Not established.","time":"Not established.","temporary":"ATA carnets are accepted (Dubai Chamber is the national guaranteeing body) — unconfirmed (U).","vf":"U","note":"No official UAE page on art export opened; only the Abu Dhabi waiver page (which refers to an export licence or shipping information as a document to supply).","src":[["Abu Dhabi Culture, Art Customs Duty Waiver Programme","https://abudhabiculture.ae/en/cultural-resources/art-customs-duty-waiver-programme"]],"none":true,"needsText":"Nothing for a painting or sculpture beyond the customs exit declaration; antiquities need the heritage authority’s consent (U).","needs":[]},"imp":{"duty":"5% GCC common customs duty on works of art at first point of entry (rate unconfirmed; not confirmed on an official page this session). Abu Dhabi’s Art Customs Duty Waiver Programme (live in 2026; reported launched Jan 2026) waives the duty for individual applicants’ artworks independently appraised at AED 10 million or more, on condition the work stays in Abu Dhabi at least three years; provenance, ownership history and due-diligence papers are mandatory.","vat":"5% VAT charged on import at the customs value plus duty (rate unconfirmed, U).","state_tax":"No emirate-level sales tax.","overlays":"Goods held in a free zone (JAFZA, DAFZ, DMCC) stay duty-suspended until they enter the mainland (U).","cpia":"n/a","vf":"S","note":"Waiver conditions read on the official page (V); the 5% duty and 5% VAT rates are U this session.","vat_rate":0.05,"duty_rate":0.05,"src":[["Abu Dhabi Culture, Art Customs Duty Waiver Programme","https://abudhabiculture.ae/en/cultural-resources/art-customs-duty-waiver-programme"]]},"aml":{"rule":"Federal Decree-Law 10 of 2025 (in force 14 Oct 2025) replaced the 2018 AML law; Cabinet Resolution 134 of 2025 (14 Dec 2025) replaced Cabinet Decision 10 of 2019. DNFBPs that must register on goAML: real-estate brokers, auditors/accountants, corporate and trust service providers, lawyers and notaries, dealers in precious metals and stones, gaming operators, VASPs. Art dealers, galleries and auction houses are not named as DNFBPs.","threshold":"AED 55,000 cash for dealers in precious metals and stones (DPMS report). Art has no statutory threshold.","asks":"Dubai and Abu Dhabi auction houses and fairs apply group KYC (ID, address, beneficial owner, source of funds) voluntarily or under free-zone (DIFC/ADGM) rules — practice, U.","vf":"S","src":[["Kayrouz & Associates, UAE goAML registration 2026","https://www.kayrouzandassociates.com/insights/uae-goaml-registration-which-businesses-must-comply-in-2026"]]},"sanctions":{"rule":"The UAE applies UN sanctions only and has adopted no Russia sanctions (U). FATF grey-listed the UAE in 2022 and removed it on 23 Feb 2024 after reforms (The National: Dh1.3bn/$354m of assets seized Mar–Jul 2023; Dh199m fines in a half-year). ‘Dubai Unlocked’ (14 May 2024; C4ADS data via OCCRP/E24) mapped over 1,000 Dubai properties held by 200 flagged owners; a sourced total for Russian-owned Dubai property was not found this session.","vf":"S","src":[["The National, UAE removed from FATF grey list, 23 Feb 2024","https://www.thenationalnews.com/business/economy/2024/02/23/uae-removed-from-financial-action-task-force-grey-list-after-reform-progress"],["Transparency International, Dubai Unlocked, 14 May 2024","https://www.transparency.org/en/press/dubai-unlocked-need-for-enhanced-anti-money-laundering-efforts.md"]]},"apost":{"hague":false,"docs":"Foreign public documents for use in the UAE (notarised provenance affidavits, powers of attorney, corporate papers) need the full legalisation chain: notary, home-state authentication, UAE embassy legalisation, then attestation by the UAE Ministry of Foreign Affairs (chain unconfirmed, U).","authority":"UAE embassies abroad and the UAE Ministry of Foreign Affairs (attestation).","fee":"Not established (MOFA attestation fee unconfirmed c.AED 150 per document, U).","time":"Not established.","vf":"V","note":"The UAE does not appear in the HCCH status table as of 3 Nov 2026, so it is not a party; the legalisation chain itself is U.","src":[["HCCH status table, Apostille Convention (UAE absent)","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Ministry of Climate Change and Environment is the CITES management authority under Federal Law 11 of 2002; ivory and other Appendix I material need CITES permits on each movement — unconfirmed (U).","vf":"U","src":[]},"freeport":{"rule":"Dubai’s free zones (DMCC, Dubai Airport Free Zone, JAFZA) offer duty-suspended storage and licences for art trading companies; no purpose-built art freeport comparable to Geneva was confirmed this session. Abu Dhabi’s waiver programme instead ties the duty relief to the work staying in the emirate for three years.","vf":"U","src":[["Abu Dhabi Culture, Art Customs Duty Waiver Programme","https://abudhabiculture.ae/en/cultural-resources/art-customs-duty-waiver-programme"]]}},"hk":{"n":"Hong Kong","exp":{"law":"No export licence for works of art. The Antiquities and Monuments Ordinance (Cap. 53) covers antiquities and monuments in Hong Kong, not the trade in imported art (U). Import and export declarations must be lodged with Customs within 14 days of shipment under the Import and Export (Registration) Regulations (U).","authority":"Customs and Excise Department (declarations); AFCD (CITES).","fee":"Declaration charge of HK$0.20 per HK$1,000 of value (U).","time":"Immediate; declaration within 14 days.","temporary":"ATA carnets accepted (Hong Kong General Chamber of Commerce issues) — U.","vf":"U","note":"No official Hong Kong page on art export or declaration opened this session.","src":[],"none":true,"needsText":"Nothing for a painting, sculpture or work on paper; a CITES licence from AFCD if the object contains listed species.","needs":[]},"imp":{"duty":"None. Hong Kong is a free port: no customs duty on art; only liquor, tobacco, hydrocarbon oil and methyl alcohol are dutiable (U).","vat":"No VAT, GST or sales tax.","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","note":"Well-established position but not confirmed on an official page this session.","vat_rate":0,"duty_rate":0,"src":[]},"aml":{"rule":"AMLO (Cap. 615) was extended on 1 Apr 2023 to dealers in precious metals and stones: Hong Kong dealers register with Customs before carrying out transactions of HK$120,000 or more; non-Hong Kong dealers (e.g. at fairs) instead report any cash transaction of HK$120,000 or more within a day. Art dealers and auction houses are not covered; the AMLO extension did not reach art.","threshold":"HK$120,000 (DPMS).","asks":"The houses apply their group KYC (ID, address, beneficial owner, source of funds) as policy, not statute (U).","vf":"V","src":[["HK Customs, Dealers in Precious Metals and Stones regime effective 1 Apr 2023","https://www.customs.gov.hk/en/customs-announcement/whats-new/index_id_117.html"]]},"sanctions":{"rule":"Hong Kong gives effect only to UN Security Council sanctions through the United Nations Sanctions Ordinance; it has adopted no Russia sanctions, though HK banks screen for US and EU exposure in practice (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Hong Kong has issued apostilles since the Convention was extended to it under the UK in 1965 and continues to after 1997 through China; the HCCH table’s extension column for China is blank, so the extension was not read on the table (U). Notarised provenance affidavits and powers of attorney for consignment are the usual art documents.","authority":"High Court Registry, Hong Kong Judiciary (U).","fee":"HK$125 per document (U).","time":"Same day to two working days (U).","vf":"U","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Protection of Endangered Species of Animals and Plants Ordinance (Cap. 586), AFCD. From 31 Dec 2021 import, re-export and commercial possession of elephant ivory are banned and all ivory possession licences have lapsed; only antique ivory (removed from the wild before 1 Jul 1925, significantly altered, not a hunting trophy) may be traded, with a qualified appraisal or accredited lab dating as proof. Maximum penalty HK$10m and 10 years.","vf":"V","src":[["HK Government press release, ivory trade ban takes effect, 31 Dec 2021","https://www.info.gov.hk/gia/general/202112/31/P2021123000620.htm"]]},"freeport":{"rule":"No freeport is needed: zero duty and no VAT leave bonded storage without a tax function. Collectors use private secure storage for security and climate control only (U).","vf":"U","src":[]}},"sg":{"n":"Singapore","exp":{"law":"No export permit for works of art; Singapore has no export-control statute for privately owned art (the National Heritage Board Act covers national monuments and public collections) — U.","authority":"Singapore Customs (TradeNet); NParks (CITES).","fee":"Permit fee c.S$2.88 per TradeNet declaration (U).","time":"Same day.","temporary":"ATA carnets: goods may stay up to 6 months within the carnet’s validity; no permit needed unless controlled; GST is charged on the selling price if a carnet item is sold; carnets for Singapore exporters are issued by the Singapore International Chamber of Commerce.","vf":"S","note":"Carnet rules read on Singapore Customs (V); the no-export-permit position is U.","src":[["Singapore Customs, ATA carnet","https://customs.gov.sg/businesses/importing-goods/temporary-import-scheme/ata-carnet"]],"none":true,"needsText":"A Customs OUT permit via TradeNet is lodged by the forwarder; no cultural licence. CITES permit from NParks for listed species (U).","needs":[]},"imp":{"duty":"No customs duty on works of art (only liquor, tobacco, petroleum and motor vehicles are dutiable) — U.","vat":"GST charged on the CIF value plus duty at import; rate 9% since 1 Jan 2024 (rate unconfirmed, U). Carnet imports are GST-free unless sold.","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","vat_rate":0.09,"duty_rate":0,"src":[["Singapore Customs, ATA carnet","https://customs.gov.sg/businesses/importing-goods/temporary-import-scheme/ata-carnet"]]},"aml":{"rule":"Precious Stones and Precious Metals (Prevention of Money Laundering and Terrorism Financing) Act 2019 regulates PSMD dealers (registration; cash transactions of S$20,000 or more reported). Art dealers and auction houses are not obliged entities — unconfirmed (U).","threshold":"S$20,000 cash (PSMD) — U.","asks":"House KYC as policy (U).","vf":"U","src":[]},"sanctions":{"rule":"Singapore imposed its own measures on Russia in March 2022 (export controls on military and dual-use goods, electronics; restrictions on dealings with designated banks); art is not within them — unconfirmed (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 16 Sep 2021 (accession 18 Jan 2021). Notarised provenance affidavits, powers of attorney and company documents are apostilled for use abroad; incoming apostilled documents are accepted without embassy legalisation.","authority":"Singapore Academy of Law (U).","fee":"S$85 per document (U).","time":"Same day to a few working days (U).","vf":"V","note":"Status read on HCCH (V); authority, fee and time are U.","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"NParks is the CITES authority under the Endangered Species (Import and Export) Act; domestic trade in elephant ivory banned from 1 Sep 2021 — unconfirmed (U).","vf":"U","src":[]},"freeport":{"rule":"Le Freeport (Changi; opened May 2010 as Singapore Freeport; c.22,500 m² over three storeys; a planned 24,000 m² phase 2 never built) was sold in 2022 to Wu Jihan for $28m, well below its c.$100m build cost, and continues as duty- and GST-suspended secure storage for art, precious metals and collectibles (The Reserve, 14 Oct 2024).","vf":"S","note":"The brief expected a 2024 sale; the source dates the sale to 2022.","src":[["The Reserve, Le Freeport overview, 14 Oct 2024","https://thereserve.sg/articles/le-freeport-an-overview-of-the-singapore-storage-facility-s-history-and-current-state"]]}},"cn":{"n":"China (mainland)","exp":{"law":"Law on the Protection of Cultural Relics (revised Nov 2024, in force 1 Mar 2025 — U). Relics leave only after examination by a provincial cultural-relics export examination agency, which seals and permits each item. Cut-offs unconfirmed (U): pre-1911 relics generally barred; 1911–1949 works restricted. NCHA’s notice of 5 May 2023 lists artists who died after 1911 in 8 categories (calligraphy and painting, ceramics, sculpture, fans, embroidery, seals, lacquer and more) whose works, or representative works, may not be exported.","authority":"National Cultural Heritage Administration (NCHA) and provincial examination agencies; China Customs.","fee":"Not established.","time":"Not established.","temporary":"ATA carnets accepted (CCPIT/China Chamber of International Commerce issues) — U. Loans abroad of museum relics need NCHA/State Council approval (U).","vf":"S","note":"The 2023 list is sourced; the general 1911/1949 cut-offs and the 2024 law revision are unconfirmed.","src":[["China Justice Observer, NCHA restricted export list of works by artists who died after 1911, May 2023","https://www.chinajusticeobserver.com/a/china-imposes-export-curbs-on-artworks-by-certain-authors-who-passed-away-after-1911"]],"none":false,"needsText":"Examination certificate and export seal for anything that may be a cultural relic; contemporary works by living artists leave on an ordinary customs declaration.","needs":[{"cat":"any","before":1949,"note":"any work made before 1949 (a cultural relic: examination, seal and permit), and works by the artists on the NCHA list of 5 May 2023 whatever the date"}],"artists":[]},"imp":{"duty":"1% MFN duty on original paintings (tariff line 9701.91; the general rate is 50%, and the 2025 tariff overlay on US-origin goods is added on top), charged on the customs value.","vat":"13% import VAT on the duty-paid value; no reduced rate for art.","state_tax":"n/a","overlays":"The US-origin surcharge above; auction imports also bear the comprehensive tax (U).","cpia":"n/a","vf":"S","note":"Rates as of Dec 2023; no 2026 official tariff schedule opened.","vat_rate":0.13,"duty_rate":0.01,"src":[["The Art Newspaper, tariffs on art and China–US relations, 26 Dec 2023","https://www.theartnewspaper.com/2023/12/26/tariffs-on-art-are-worsening-frayed-china-us-relations-deepening-ongoing-trade-war"],["China tariff, 9701.91.19 (mirror, read 9 Nov 2026)","https://treayo.com/en/hs/china/97019119"]]},"aml":{"rule":"Anti-Money Laundering Law revised 8 Nov 2024, in force 1 Jan 2025, extends obligations to ‘specific non-financial institutions’ to be designated (real estate, precious metals, accountants and lawyers); art dealers and auction houses not designated as of 2026 — unconfirmed (U).","threshold":"Not established.","asks":"Auction houses verify ID and collect a bidder deposit; source-of-funds checks are not statutory (U).","vf":"U","src":[]},"sanctions":{"rule":"China has no Russia sanctions; large Chinese banks nonetheless screen for US secondary-sanctions exposure and have refused some Russia-linked payments (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 7 Nov 2023 (accession 8 Mar 2023; some states objected, shown as A** on the HCCH table). Notarised provenance affidavits, powers of attorney and company papers are apostilled; foreign apostilled documents no longer need Chinese consular legalisation, except for objecting states.","authority":"Ministry of Foreign Affairs and authorised provincial Foreign Affairs Offices (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Endangered Species Import and Export Management Office (National Forestry and Grassland Administration) issues permits; domestic commercial ivory processing and trade banned from 31 Dec 2017 — unconfirmed (U).","vf":"U","src":[]},"freeport":{"rule":"Bonded art storage operates in the Shanghai free-trade zone (the West Bund art bonded warehouse, whose 2023 import/export guide The Art Newspaper cites) and in Beijing’s Tianzhu comprehensive bonded zone; works may be shown at fairs under bond and pay duty and VAT only on release to the mainland. Fees not published (U).","vf":"U","src":[["The Art Newspaper, 26 Dec 2023 (West Bund guide)","https://www.theartnewspaper.com/2023/12/26/tariffs-on-art-are-worsening-frayed-china-us-relations-deepening-ongoing-trade-war"]]}},"jp":{"n":"Japan","exp":{"law":"Law for the Protection of Cultural Properties: National Treasures, Important Cultural Properties and other authorised important fine arts may not be exported as a rule. Antique fine arts leaving Japan need the Agency for Cultural Affairs’ certificate (Kobijutsuhin yushutsu kansa shomei) confirming the item is not designated, which speeds customs clearance. Other art exports freely.","authority":"Agency for Cultural Affairs (Bunkacho).","fee":"Not established.","time":"Not established.","temporary":"ATA carnets accepted (Japan Commercial Arbitration Association issues) — U.","vf":"V","src":[["Agency for Cultural Affairs, international exchange of cultural properties","https://www.bunka.go.jp/english/policy/cultural_properties/international/index.html"]],"none":true,"needsText":"ACA export examination certificate for antique fine arts; nothing for contemporary art.","needs":[],"listed":"A National Treasure or an Important Cultural Property may not leave; an antique leaves with the Agency for Cultural Affairs’ certificate that it is not designated."},"imp":{"duty":"0% on chapter 97 (U).","vat":"10% consumption tax on import value plus duty (U).","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","vat_rate":0.1,"duty_rate":0,"src":[]},"aml":{"rule":"Act on Prevention of Transfer of Criminal Proceeds covers dealers in precious metals and stones, not art dealers; antique dealers are licensed under the Secondhand Articles Dealer Act (U).","threshold":"Not established.","asks":"House KYC as policy (U).","vf":"U","src":[]},"sanctions":{"rule":"Japan bans export of luxury goods to Russia, works of art included (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 27 Jul 1970 (ratified 28 May 1970). Ministry of Foreign Affairs apostilles notarised and official documents (U).","authority":"Ministry of Foreign Affairs, Tokyo and Osaka (U).","fee":"Free (U).","time":"Next working day (U).","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"METI issues CITES import/export approvals; domestic ivory trade continues under registration (U).","vf":"U","src":[]},"freeport":{"rule":"No art freeport; bonded warehouses exist at ports and airports (U).","vf":"U","src":[]}},"kr":{"n":"South Korea","exp":{"law":"National heritage framework (amended 2024): ‘general movable cultural heritage’ may not leave Korea or be sold abroad without permission and appraisal by the Korea Heritage Service. Since 23 Jul 2024 only works made before 1946 fall in the category (formerly anything over 50 years old), so post-1946 Korean art exports freely.","authority":"Korea Heritage Service (formerly Cultural Heritage Administration).","fee":"Not established.","time":"Not established.","temporary":"ATA carnets accepted (Korea Chamber of Commerce issues) — U.","vf":"S","src":[["Korea JoongAng Daily, government loosens restrictions on sales of Korean art and heritage items, 23 Jul 2024","https://www.koreajoongangdaily.com/lifestyle/govt-loosens-restrictions-on-sales-of-korean-art-and-heritage-items/10535085"]],"none":false,"needsText":"KHS appraisal/permit for pre-1946 items of artistic or academic value; nothing for later works.","needs":[{"cat":"any","before":1946,"note":"any work made before 1946 (general movable cultural heritage: appraisal and permit from the Korea Heritage Service); later works leave freely"}]},"imp":{"duty":"0% on chapter 97 (U).","vat":"Original works of art (paintings, sculpture, a hand-made drawing) are exempt from VAT on import and on sale (VAT Act art. 27(15), Enforcement Decree art. 56(17)); the 10% is charged on editions, prints and photographs, and the form’s ‘drawing or print’ is taxed as the edition it most often is.","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"S","vat_rate":0,"duty_rate":0,"src":[],"vat_kinds":{"photo":0.1,"paper":0.1}},"aml":{"rule":"Art dealers are not obliged entities under the Act on Reporting and Using Specified Financial Transaction Information (U).","threshold":"Not established.","asks":"House KYC as policy (U).","vf":"U","src":[]},"sanctions":{"rule":"Korea restricts exports of strategic goods to Russia; art not covered (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 14 Jul 2007 (accession 25 Oct 2006).","authority":"Ministry of Foreign Affairs and Ministry of Justice (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Ministry of Environment is the CITES authority (U).","vf":"U","src":[]},"freeport":{"rule":"Bonded storage at Incheon used for fairs (Frieze Seoul, Kiaf) (U).","vf":"U","src":[]}},"qa":{"n":"Qatar","exp":{"law":"Antiquities Law No. 2 of 1980: antiquities may not leave without Qatar Museums’ permission; no licence for contemporary art — unconfirmed (U).","authority":"Qatar Museums; General Authority of Customs.","fee":"Not established.","time":"Not established.","temporary":"ATA carnets accepted (Qatar Chamber) — U.","vf":"U","src":[],"none":true,"needsText":"Nothing for modern works; permission for antiquities (U).","needs":[]},"imp":{"duty":"5% GCC common tariff on works of art (U).","vat":"No VAT in force (U).","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","vat_rate":0,"duty_rate":0.05,"src":[]},"aml":{"rule":"Law No. 20 of 2019 on AML/CFT covers DNFBPs including dealers in precious metals and stones; art dealers not named (U).","threshold":"Not established.","asks":"Not established.","vf":"U","src":[]},"sanctions":{"rule":"No Russia sanctions (U).","vf":"U","src":[]},"apost":{"hague":false,"docs":"Not a party (absent from the HCCH table, 3 Nov 2026): documents need embassy legalisation and attestation by Qatar’s Ministry of Foreign Affairs (chain U).","authority":"Qatar embassies; Ministry of Foreign Affairs.","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (Qatar absent)","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Ministry of Environment and Climate Change is the CITES authority (U).","vf":"U","src":[]},"freeport":{"rule":"Qatar Free Zones offer bonded storage; no art-specific freeport (U).","vf":"U","src":[]}},"sa":{"n":"Saudi Arabia","exp":{"law":"Antiquities, Museums and Urban Heritage Law (2014): antiquities may not leave without a Heritage Commission permit; no licence for contemporary art — unconfirmed (U).","authority":"Heritage Commission (Ministry of Culture); ZATCA customs.","fee":"Not established.","time":"Not established.","temporary":"ATA carnets accepted (Federation of Saudi Chambers) — U.","vf":"U","src":[],"none":true,"needsText":"Nothing for modern works; Heritage Commission permit for antiquities (U).","needs":[]},"imp":{"duty":"5% customs duty on works of art under the GCC tariff (U).","vat":"15% VAT on import (U).","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","note":"The one Saudi page opened (calcmytariff) covered US duties on Saudi goods, not Saudi import duty.","vat_rate":0.15,"duty_rate":0.05,"src":[]},"aml":{"rule":"Anti-Money Laundering Law (Royal Decree M/20 of 2017) covers DNFBPs including dealers in precious metals and stones; art dealers not named (U).","threshold":"Not established.","asks":"Not established.","vf":"U","src":[]},"sanctions":{"rule":"No Russia sanctions (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 7 Dec 2022 (accession 8 Apr 2022). Ministry of Foreign Affairs apostilles documents; incoming apostilled documents replace embassy legalisation (U for procedure).","authority":"Ministry of Foreign Affairs (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"National Center for Wildlife is the CITES authority (U).","vf":"U","src":[]},"freeport":{"rule":"Special Integrated Logistics Zone at Riyadh airport offers bonded storage; no art freeport (U).","vf":"U","src":[]}},"in":{"n":"India","exp":{"law":"Antiquities and Art Treasures Act 1972: no antiquity (over 100 years; 75 years for manuscripts and documents) or declared art treasure may be exported except by the Central Government or its agency (s.3); the ‘Navratna’ artists (Tagore, Amrita Sher-Gil, Jamini Roy, Raja Ravi Varma and others; notifications 1976 and 1979) are barred from export though owned and sold at home. Antiquities must be registered; dealers licensed with stock registers and monthly returns.","authority":"Director General, Archaeological Survey of India; Customs.","fee":"Not established.","time":"Not established.","temporary":"ATA carnets accepted (FICCI issues) — U.","vf":"S","src":[["Aarna Law via Mondaq, cultural property law in India 2026, 6 Mar 2026","https://www.mondaq.com/india/real-estate/1754216/cultural-property-law-in-india-2026-repatriation-export-rules-aata-compliance"]],"none":false,"needsText":"For anything that might be an antiquity, an ASI non-antiquity certificate for customs (process and timing not opened this session, U); nothing for recent works by other artists.","needs":[{"cat":"any","artists":true,"bar":true,"note":"the declared art treasures (Tagore, Sher-Gil, Jamini Roy, Ravi Varma, Nandalal Bose and others) may not leave at any age"},{"cat":"any","age":100,"value":0,"bar":true,"note":"any object over 100 years old is an antiquity and may not be exported except by the government"}],"artists":["Rabindranath Tagore","Amrita Sher-Gil","Jamini Roy","Raja Ravi Varma","Nandalal Bose"]},"imp":{"duty":"10% basic customs duty on chapter 97 plus the 10% social welfare surcharge on the duty: about 11% of the value (U); IGST is charged on the duty-paid value.","vat":"IGST 5% on import (cut from 12% on 22 Sep 2025, when chapter 97 moved to the 5% slab), charged on the value plus the 11% duty.","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","vat_rate":0.05,"duty_rate":0.11,"src":[["GST on HSN chapter 97 (secondary, read 9 Nov 2026)","https://disytax.com/hsn-97-works-of-art-gst-rate/"]]},"aml":{"rule":"Prevention of Money Laundering Act 2002: dealers in precious metals and stones are reporting entities above INR 1m cash; art dealers not notified (U).","threshold":"Not established.","asks":"Not established.","vf":"U","src":[]},"sanctions":{"rule":"No Russia sanctions (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 14 Jul 2005 (accession 26 Oct 2004; shown with objections, A**). Ministry of External Affairs apostilles after state authentication (U).","authority":"Ministry of External Affairs (U).","fee":"INR 50 per document (U).","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Wildlife Crime Control Bureau / Ministry of Environment; ivory trade banned domestically since 1991 (U).","vf":"U","src":[]},"freeport":{"rule":"No art freeport; bonded warehouses under the Customs Act (U).","vf":"U","src":[]}},"ru":{"n":"Russia","exp":{"law":"Law 4804-1 of 15 Apr 1993 on the export and import of cultural valuables, as rewritten by Federal Law 435-FZ of 28 Dec 2017 (in force 2018). Since 2014 ‘export’ means leaving the EAEU. Items on EAEU common list 2.20 (EEC Board Decision 30 of 21 Apr 2015) leave on a Ministry of Culture conclusion (individuals; temporary export) or a Minpromtorg licence (permanent export by legal entities).","authority":"Ministry of Culture (conclusions, expert examination); Minpromtorg (licences); Federal Customs Service.","fee":"State fee for the permit not confirmed (memory: RUB 5–10% of value for permanent export of cultural valuables; U); expert conclusion from RUB 20,000.","time":"Not established.","temporary":"Temporary export on a Ministry of Culture conclusion with an obligation to return; ATA carnets are accepted in Russia (Chamber of Commerce and Industry) — U.","vf":"S","note":"The law’s text was not readable on ConsultantPlus (paywalled); the procedure is from a broker’s guide. 2022–2026 wartime changes to cultural-valuables export were not found.","src":[["ConsultantPlus, Law 4804-1 (title and amendment list only)","https://www.consultant.ru/document/cons_doc_LAW_1905/"],["IFCG customs broker, EAEU list 2.20 cultural valuables","https://www.ifcg.ru/services/docs/non-tariff/2.20/"]],"none":false,"needsText":"Ministry of Culture conclusion or Minpromtorg licence for a cultural valuable; an expert conclusion that a work is not a cultural valuable (from RUB 20,000, broker’s figure) where customs doubt it. The 435-FZ ‘special value’ list (e.g. pre-1917 art) may leave only under an obligation to return. The 50/100-year categories were not read on a primary page (U).","needs":[{"cat":"any","before":1917,"temporaryOnly":true,"note":"pre-1917 works of special value may leave only under an obligation to return"},{"cat":"any","age":50,"value":0,"note":"a cultural valuable on the EAEU list 2.20 leaves on a Ministry of Culture conclusion (a private owner, or a temporary export) or a Minpromtorg licence (a permanent export by a company); the 50-year line is unconfirmed"}]},"imp":{"duty":"EAEU common tariff on works of art is 0% (U).","vat":"20% import VAT unless the item is a cultural valuable recognised by the Ministry of Culture (exempt) — U.","state_tax":"n/a","overlays":"Counter-sanctions do not restrict art imports; payment from abroad is the obstacle (U).","cpia":"n/a","vf":"U","vat_rate":0.2,"duty_rate":0,"src":[]},"aml":{"rule":"Federal Law 115-FZ: art dealers and auction houses are not obliged entities; dealers in precious metals and stones, realtors, lawyers and notaries are (U).","threshold":"Not established.","asks":"Not established.","vf":"U","src":[]},"sanctions":{"rule":"Capital controls (CBR): residents and non-residents from friendly states may transfer up to $1m (or equivalent) a month to a foreign bank account and $10,000 a month via money-transfer systems; non-working non-residents from unfriendly states and unfriendly-state companies may not transfer abroad. Extended 1 Oct 2025–31 Mar 2026 (CBR, 26 Sep 2025); renewals since not opened (U). Cash currency export over $10,000 banned by Decree 81 of 1 Mar 2022 (U).","vf":"S","note":"cbr.ru refused the fetch; the limits are read from three press reports of the CBR release.","src":[["Pravo.ru, CBR extends limits on transfers abroad, 26 Sep 2025","https://pravo.ru/news/260549/"],["Inc. Russia, CBR extends limits for six months, 26 Sep 2025","https://incrussia.ru/news/bank-rossii-prodlil-na-polgoda-ogranicheniya-na-perevody-sredstv-za-rubezh/"],["Profile.ru, 26 Sep 2025","https://profile.ru/?p=1760096"]]},"apost":{"hague":true,"docs":"Party by succession (4 Sep 1991), in force 31 May 1992. Notarial documents are apostilled by the Ministry of Justice and its regional departments; US apostilled affidavits are accepted in Russia and vice versa, sanctions aside (U for authority).","authority":"Ministry of Justice of the Russian Federation and territorial bodies; ZAGS for civil records (U).","fee":"RUB 2,500 state fee per document (U).","time":"Up to 5 working days (U).","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Rosprirodnadzor is the CITES management authority (U).","vf":"U","src":[]},"freeport":{"rule":"No art freeport (U).","vf":"U","src":[]}},"mx":{"n":"Mexico","exp":{"law":"Federal Law on Archaeological, Artistic and Historic Monuments and Zones (1972): archaeological objects are national property and cannot leave; works declared ‘artistic monuments’ by decree (Velasco 1943, Orozco and Rivera 1959, Dr Atl 1964, Siqueiros 1980, Kahlo 1984, Herrán 1988, Varo 2001, Izquierdo 2002; Vlady provisional 2023) need INBAL permission and permanent export is refused in practice. The Supreme Court took up (8–1, 2026) a bank’s challenge to the Kahlo decree; no ruling as of Aug 2026.","authority":"INBAL (artistic monuments); INAH (archaeological and historic); SAT customs.","fee":"Not established.","time":"Not established.","temporary":"Temporary export of artistic monuments is permitted for exhibitions with INBAL approval; the Gelman collection’s 2026 approval for exhibition abroad is under litigation.","vf":"S","src":[["Snell & Wilmer, Frida Kahlo, artistic monuments and the right to permanently export, 6 Aug 2026","https://www.swlaw.com/publication/frida-kahlo-artistic-monuments-and-the-right-to-permanently-export-mexican-supreme-court-to-consider-the-scope-of-executive-regulatory-power-in-the-face-of-federal-statute/"]],"none":false,"needsText":"INBAL temporary-export permit for artistic monuments; INAH for archaeological/historic items; nothing for other art (U).","needs":[{"cat":"any","artists":true,"bar":true,"note":"the complete works of the artists declared artistic monuments (Velasco, Orozco, Rivera, Dr Atl, Siqueiros, Kahlo, Herrán, Varo, Izquierdo; Vlady provisionally) need INBAL’s permit, refused for permanent export; archaeological objects are national property"}],"artists":["José María Velasco","José Clemente Orozco","Diego Rivera","Gerardo Murillo","Dr Atl","David Alfaro Siqueiros","Frida Kahlo","Saturnino Herrán","Remedios Varo","María Izquierdo","Vlady"]},"imp":{"duty":"0% on chapter 97 (U).","vat":"16% IVA on import (U).","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","vat_rate":0.16,"duty_rate":0,"src":[]},"aml":{"rule":"Federal Law for the Prevention and Identification of Operations with Illicit Resources (2012): art and antique sales are ‘vulnerable activities’ with reporting above a UMA-based threshold (U).","threshold":"Not established.","asks":"Not established.","vf":"U","src":[]},"sanctions":{"rule":"No Russia sanctions (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 14 Aug 1995 (accession 1 Dec 1994). Federal documents apostilled by the Secretaría de Gobernación; state documents by state governments (U).","authority":"Secretaría de Gobernación; state governments (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"SEMARNAT is the CITES authority (U).","vf":"U","src":[]},"freeport":{"rule":"No art freeport (U).","vf":"U","src":[]}},"br":{"n":"Brazil","exp":{"law":"Decree-Law 25 of 1937 (tombamento) and Law 4,845 of 1965: works of art and documents produced in Brazil up to the end of the monarchy (1889) and listed objects may not leave the country; IPHAN authorises temporary exits for exhibitions; other art exports freely — unconfirmed (U).","authority":"IPHAN; Receita Federal.","fee":"Not established.","time":"Not established.","temporary":"ATA carnets accepted since 2016 (CNI issues) — U.","vf":"U","note":"No Brazilian source surfaced in the combined Mexico/Brazil search.","src":[],"none":false,"needsText":"IPHAN authorisation for listed or pre-1889 Brazilian works; nothing for other art (U).","needs":[{"cat":"any","before":1890,"bar":true,"note":"works produced in Brazil up to 1889 and listed (tombado) works may not leave; IPHAN allows temporary exits for exhibitions"}]},"imp":{"duty":"4% import duty on chapter 97 (U).","vat":"ICMS at the state rate (c.18%) plus federal PIS/COFINS (U).","state_tax":"ICMS varies by state (U).","overlays":"PIS/COFINS and state ICMS on import (U).","cpia":"n/a","vf":"U","vat_rate":0.18,"duty_rate":0.04,"src":[]},"aml":{"rule":"Law 9,613/1998: dealers in art, antiques and luxury goods are obliged to register with COAF and report (U).","threshold":"Not established.","asks":"Not established.","vf":"U","src":[]},"sanctions":{"rule":"No Russia sanctions (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 14 Aug 2016 (accession 2 Dec 2015). Apostilles issued by authorised notaries (cartórios) under the National Council of Justice (U).","authority":"Cartórios authorised by the CNJ (U).","fee":"Set by state notary tables (U).","time":"Same day (U).","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"IBAMA is the CITES authority (U).","vf":"U","src":[]},"freeport":{"rule":"No art freeport (U).","vf":"U","src":[]}},"au":{"n":"Australia","exp":{"law":"Protection of Movable Cultural Heritage Act 1986: ‘Australian protected objects’ on the National Cultural Heritage Control List (categories judged by age, value, rarity and representation in public collections, e.g. Indigenous art, documents, furniture) need an export permit; a prohibited-exports register lists refused items. Class A objects cannot be exported; Class B need a permit (classes named but not defined on the page).","authority":"Cultural Property Section, Office for the Arts (Department of Infrastructure, Transport, Regional Development, Communications and the Arts); Minister for the Arts.","fee":"Not stated on the official page.","time":"‘Can take many months’ (official page).","temporary":"Permits may be temporary and time-limited; public institutions hold General Permits for Class B loans; a certificate of exemption obtained before an object from an overseas collection enters Australia lets it leave again without a permit.","vf":"S","note":"Value and age thresholds for fine art (e.g. the A$250,000 / 30-year test) are in the Regulations, which were not opened.","src":[["Office for the Arts, exporting cultural property from Australia","https://arts.gov.au/what-we-do/cultural-heritage/movable-cultural-heritage/exporting-cultural-property-australia"]],"none":false,"needsText":"Permit application through the Office for the Arts portal; expert examiner, then the National Cultural Heritage Committee, then the Minister or delegate. Outcomes: not an APO, permit granted, or refused. Freight companies may be prosecuted for carrying an APO without a permit.","needs":[{"cat":"any","age":30,"value":250000,"cur":"aud","note":"Australian works on the National Cultural Heritage Control List: the age and value tests (30 years and A$250,000 for fine art, A$100,000 for Indigenous works) are in the Regulations, not opened; foreign works held under 50 years are outside the list"}]},"imp":{"duty":"0% on chapter 97 (U).","vat":"10% GST on import value plus freight and insurance (U).","state_tax":"n/a","overlays":"None.","cpia":"n/a","vf":"U","vat_rate":0.1,"duty_rate":0,"src":[]},"aml":{"rule":"AML/CTF Amendment Act 2024 extends obligations to dealers in precious metals and stones and other ‘tranche 2’ professions from 1 Jul 2026; art dealers are not included (U).","threshold":"A$10,000 cash threshold transaction reports (U).","asks":"Not established.","vf":"U","src":[]},"sanctions":{"rule":"Autonomous Sanctions Regulations: export of luxury goods to Russia banned from 2022, works of art included (U).","vf":"U","src":[]},"apost":{"hague":true,"docs":"Party since 16 Mar 1995 (accession 11 Jul 1994). DFAT apostilles notarised and public documents (U).","authority":"Department of Foreign Affairs and Trade (U).","fee":"A$100 per document (U).","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention","https://www.hcch.net/en/instruments/conventions/status-table/?cid=41"]]},"cites":{"rule":"Department of Climate Change, Energy, the Environment and Water is the CITES authority under the EPBC Act; pre-1975 ivory needs a pre-Convention certificate (U).","vf":"U","src":[]},"freeport":{"rule":"No art freeport (U).","vf":"U","src":[]}},"pe":{"n":"Peru","exp":{"none":false,"law":"The General Law of the Cultural Heritage of the Nation (Law 28296): pre-Hispanic, colonial and republican objects of cultural value may not be exported; a contemporary work needs the Ministry of Culture’s certificate that it is not cultural heritage before it leaves.","authority":"the Ministry of Culture","needs":[{"cat":"any","before":1900,"bar":true,"note":"heritage (pre-Hispanic, colonial, republican) may leave only for exhibition, by supreme resolution"},{"cat":"any","age":0,"value":0,"note":"every other work needs the Ministry’s certificate before export"}],"time":"1 to 3 weeks for the certificate","fee":"a small fee","src":[],"vf":"U"},"imp":{"duty":"No duty on works of art.","duty_rate":0,"vat":"IGV at 18% on import.","vat_rate":0.18,"src":[],"vf":"U"},"aml":{"rule":"The Financial Intelligence Unit lists dealers in works of art and antiques among obliged persons; transactions are registered and reported above thresholds.","threshold":"$10,000 (registry)","asks":"identity and the record of the transaction","src":[],"vf":"U"},"sanctions":{"rule":"Peru applies United Nations sanctions only.","src":[],"vf":"U"},"apost":{"hague":true,"authority":"the Ministry of Foreign Affairs","fee":"about S/ 30 a document","docs":"notarised affidavit; power of attorney","src":[],"vf":"U"},"cites":{"rule":"SERFOR issues CITES permits.","src":[],"vf":"U"}},"bd":{"n":"Bangladesh","exp":{"law":"Antiquities Act 1968 (as amended 1976): no antiquity may be exported without a licence from the Director General of Archaeology; the Act reaches objects of historical or artistic interest and the Government may declare any object an antiquity. No export licence is known for a contemporary painting or sculpture (U).","authority":"Department of Archaeology, Ministry of Cultural Affairs; Bangladesh Customs (National Board of Revenue).","fee":"Not established.","time":"Not established.","temporary":"Bangladesh is not in the ATA carnet chain (unconfirmed, U); temporary exports move on an ordinary customs bond.","treasure":"Found antiquities belong to the State under the 1968 Act (U).","vf":"U","note":"No Bangladesh heritage or customs page opened this session; the budget went to the exchange-control law. Everything here is unconfirmed.","src":[],"none":false,"needsText":"An export declaration through the customs system; for anything the Department of Archaeology might treat as an antiquity, its licence or a no-objection letter. Not opened on an official page this session (U).","needs":[]},"imp":{"duty":"Chapter 97 attracts customs duty under Bangladesh’s tariff (rate not confirmed; 25% ad valorem on 9701 recalled, U) plus the usual supplementary and advance taxes.","vat":"15% standard VAT, charged on import (U).","special":"No reduced rate or art-specific relief found (U).","state_tax":"None.","overlays":"Advance income tax and advance trade VAT are collected at import on most goods (U).","cpia":"Bangladesh is a party to the 1970 UNESCO Convention (U).","vf":"U","note":"Not opened this session.","vat_rate":0.15,"duty_rate":0,"src":[]},"aml":{"rule":"Money Laundering Prevention Act 2012 (amended 2015), supervised by the Bangladesh Financial Intelligence Unit. Reporting organisations are banks, financial institutions, insurers, money changers, remitters, dealers in precious metals and stones, real-estate developers, lawyers, accountants and NGOs; art dealers and auctioneers are not listed (U). The 2022 overseas-investment rules state that misuse of an approved investment ‘will be treated as money laundering’ (press report).","threshold":"Cash transaction reports above BDT 1,000,000 (10 lakh) in a day (U).","asks":"Banks ask for national ID, the source of funds and the purpose of any outward remittance; authorised dealers submit remittance applications to Bangladesh Bank (U).","vf":"U","note":"The Act and the BFIU circulars were not opened.","src":[["Prothom Alo, Bangladesh allows local firms to make overseas equity investment, 27 Jan 2022","https://en.prothomalo.com/business/local/bangladesh-allows-local-firms-to-make-overseas-equity-investment"]]},"sanctions":{"rule":"Bangladesh applies the UN Security Council lists through the Anti-Terrorism Act 2009 and BFIU circulars; it has no autonomous sanctions on Russia (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":true,"docs":"Bangladesh acceded on 29 Jul 2024; the Convention entered into force for it on 30 Mar 2025 (accession marked A**, so it operates only with Contracting Parties that did not object). Documents for a sale abroad (powers of attorney, notarised provenance affidavits, company papers) are apostilled rather than legalised at the consulate.","authority":"Ministry of Foreign Affairs (Consular and Welfare Wing), Dhaka — unconfirmed (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026; 130 Contracting Parties)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1982; the Wildlife (Conservation and Security) Act 2012 bans trade in ivory and listed species products; CITES permits are issued by the Forest Department (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"No art freeport. Bonded warehouses serve export industries only (U).","vf":"U","src":[]},"capital":{"rule":"Exchange control rests on the Foreign Exchange Regulation Act 1947 (FERA, last amended by Act XVII of 2015). s.4(1): nobody but an authorised dealer may buy, borrow, sell, lend or exchange foreign exchange without Bangladesh Bank’s general or special permission; s.4(5) lets a resident buy foreign exchange from an authorised dealer only for a current-account transaction; s.4(6) lets Bangladesh Bank specify which capital-account transactions are permissible. s.5(1): a resident may not make any payment to or for the credit of a person resident outside Bangladesh without Bangladesh Bank’s exemption. s.8(2): taking foreign exchange, gold or jewellery out of the country needs permission. s.19(1) lets the Government or the Bank require residents to repatriate foreign exchange, foreign securities and foreign property. s.23: up to seven years’ imprisonment, a fine and confiscation. A resident is anyone in Bangladesh six months of the last twelve (s.2(hhh)). Buying a work of art abroad with one’s own money is a capital-account transaction for which no general permission was found; it would need Bangladesh Bank’s special permission, and this session found no published route for a resident individual. A non-resident buyer who paid from abroad can repatriate sale proceeds through an authorised dealer against the record of the inward remittance (Form C for inward remittances of $2,000 or more, 2009 guidelines).","limits":"Overseas equity investment: only exporters, from their Export Retention Quota accounts, up to 20% of the firm’s average annual export earnings over five years or under 25% of net assets in the latest audited accounts, approved by a 15-member committee chaired by the Bangladesh Bank governor under the Capital Account Transaction (Overseas Equity Investment) Rules 2022 (issued 9 Jan 2022; the press report cites s.26 of FERA, the Act text opened puts rule-making in s.27 and permissible capital transactions in s.4(6)). Returns must be remitted home within 30 days; misuse is treated as money laundering. Personal purposes: the 2009 guidelines allowed travellers cash and travellers’ cheques of up to $1,000 equivalent from money changers ($200 without a visa) within an annual travel quota; press headlines of 2025 report the annual private travel quota raised to $18,000 and a master circular of 30 Sept consolidating outward-remittance rules for travel, private transfers, dividends, institutional payments and international cards (figures not read on the circular itself, U). Companies may remit $30,000 a year for an overseas office (2009 guidelines).","routes":"An exporter’s approved overseas equity investment from its ERQ; a non-resident investor’s funds brought in and recorded (Form C; non-resident Taka and NITA accounts; sale proceeds of listed securities remittable without prior approval at the day’s market price, unlisted shares with prior approval on audited net asset value; dividends on an auditor-certified form after non-resident tax); inheritance and gifts are not a route for a resident to export capital. There is no lawful route for a resident individual to wire a sum abroad to buy a work of art; the lawful transformation starts only with funds that are already outside Bangladesh with permission or that belong to a non-resident.","vf":"S","note":"The Act was read on a law-firm mirror (bdlaws.minlaw.gov.bd not opened); the 2022 Rules’ own text on fid.portal.gov.bd refused the fetch (robots), so the ceilings rest on the press report; the personal quotas rest on 2009 guidelines and 2025 headlines. Bangladesh Bank’s site was not opened. The s.23 penalty and the resident definition are read on the Act.","src":[["Foreign Exchange Regulation Act 1947 (Bangladesh), text on a law-firm mirror","https://cdn2.ogrlegal.com/files/bida/act/Foreign-Exchange-Regulation-Act-1947.pdf"],["Prothom Alo, Bangladesh allows local firms to make overseas equity investment, 27 Jan 2022","https://en.prothomalo.com/business/local/bangladesh-allows-local-firms-to-make-overseas-equity-investment"],["JETRO, Bangladesh foreign exchange guidelines (Bangladesh Bank text as at 31 May 2009; compiled Mar 2014)","https://www.jetro.go.jp/ext_images/jfile/report/07001789/bd_foreignexchange.pdf"],["The Daily Star, Bangladesh Bank consolidates outward remittance rules (master circular of 30 Sept, valid one year)","https://online-d11.thedailystar.net/business/news/bangladesh-bank-consolidates-outward-remittance-rules-4002431"]]}},"ca":{"n":"Canada","exp":{"law":"Cultural Property Export and Import Act, RSC 1985 c. C-51, and the Canadian Cultural Property Export Control List (CRC c. 448). An export permit is needed for any object on the Control List that is 50 years old or more and whose maker is no longer living (s.4(3) of the Act bars listing anything under 50 years old or made by a living person), whatever the reason for export, whether permanent or temporary, and however long it has been in Canada.","authority":"CBSA permit-issuing offices issue permanent and temporary permits; an expert examiner reviews permanent applications; general permits come from the Minister of Canadian Heritage (Movable Cultural Property Program); the Canadian Cultural Property Export Review Board hears appeals.","fee":"No fee is stated on the Canadian Heritage page (U whether it is free).","time":"Not stated. If a permanent permit is refused and the Review Board upholds the refusal it sets a delay of two to six months during which designated Canadian institutions may buy the object; without an appeal a new application can be made only after two years. The Board can determine a fair cash offer.","temporary":"Temporary permits (exhibition, conservation, research) are granted automatically; the object must return within five years and a notice of return is due within 15 days.","treasure":"Objects recovered from Canadian soil, territorial sea or inland waters may be listed at any value (s.4(2)(a)); the Act is a heritage-retention regime, not a treasure-trove regime.","vf":"V","note":"Exporting controlled property without a permit is a criminal offence (fines, imprisonment or both).","src":[["Cultural Property Export and Import Act, s.4 (justice.laws.gc.ca)","https://laws-lois.justice.gc.ca/eng/acts/c-51/section-4.html"],["Canadian Cultural Property Export Control List, Group V Objects of Fine Art","https://laws-lois.justice.gc.ca/eng/regulations/C.R.C.,_c._448/page-6.html"],["Canadian Heritage, Cultural property export permits (modified 13 Jan 2023)","https://www.canada.ca/en/canadian-heritage/services/export-permits-cultural-property.html"]],"none":false,"needsText":"Group V (fine art) thresholds by fair market value in Canada: made by a person who at any time ordinarily resided in Canada — drawings and prints over C$5,000, paintings and sculptures over C$15,000, other media over C$5,000; Canadian-connected works (commissioned by a Canadian resident, Canadian theme, or tied to a prominent Canadian person, institution or event) — over C$7,500 / C$20,000 / C$7,500; works made outside Canada with no such connection — drawings and prints over C$15,000, paintings and sculptures over C$30,000, other media over C$20,000. Photographs fall under Group VII. Below the thresholds, or for a living artist, nothing but the shipper’s export declaration.","needs":[{"cat":"painting","age":50,"value":30000,"cur":"cad","note":"a painting 50 years old by an artist no longer living, over C$30,000 (C$15,000 if the artist lived in Canada; C$20,000 for a Canadian subject): a permit from Canadian Heritage, which may be refused and referred to the Review Board for up to six months"},{"cat":"sculpture","age":50,"value":30000,"cur":"cad","note":"a sculpture 50 years old by an artist no longer living, over C$30,000 (C$15,000 if the artist lived in Canada): a permit from Canadian Heritage"},{"cat":"paper","age":50,"value":15000,"cur":"cad","note":"a drawing or print 50 years old by an artist no longer living, over C$15,000 (C$5,000 if the artist lived in Canada): a permit from Canadian Heritage"},{"cat":"photo","age":50,"value":15000,"cur":"cad","note":"a photograph 50 years old by an artist no longer living, over the Group VII threshold (taken here as C$15,000, U): a permit from Canadian Heritage"}],"dead":true},"imp":{"duty":"Customs Tariff chapter 97 (T2025): paintings, drawings and pastels, original prints, original sculpture, collectors’ pieces and antiques over 100 years are ‘Free’ at the MFN rate and under all 21 preferential agreements where they are originals by artists; the ‘other’ lines for hand-painted or decorated work that is not an original by an artist carry 5.5% (paintings) and 7% (mosaics, other works) MFN, Free under the agreements. Chapter notes exclude mass-produced reproductions and works of conventional commercial craftsmanship.","vat":"5% GST is collected by CBSA on the value for duty at import; HST or provincial sales tax follows where the work is delivered or for commercial importers’ accounts (unconfirmed, U).","special":"Works imported for a public institution or museum may be relieved under tariff item 9812 and the Cultural Property Export and Import Act donation route (U).","state_tax":"Provincial HST/PST at the place of delivery (Ontario 13% HST, Quebec 9.975% QST plus GST, Alberta GST only) — unconfirmed (U).","overlays":"Canada’s 2025–26 counter-tariffs on US goods and the US tariffs on Canadian goods were not checked for chapter 97 this session (U). Russian-origin luxury goods: the import ban in Schedule 6 Part 2 does not cover art (see sanctions).","cpia":"Under s.37 of the Cultural Property Export and Import Act Canada bars the import of foreign cultural property illegally exported from a reciprocating state (1970 UNESCO Convention) — unconfirmed (U).","vf":"V","note":"Duty rates read on the CBSA 2025 tariff (the 2026 tariff not opened); GST/HST at import carried unconfirmed.","vat_rate":0.05,"duty_rate":0,"src":[["CBSA, Customs Tariff 2025, Chapter 97 (archived page, issued 1 Jan 2025)","https://www.cbsa-asfc.gc.ca/trade-commerce/tariff-tarif/2025/html/00/ch97-eng.html"]]},"aml":{"rule":"Proceeds of Crime (Money Laundering) and Terrorist Financing Act. Reporting entities that must file electronic funds transfer reports with FINTRAC: financial entities, money services businesses and foreign MSBs, casinos, life insurers (when they offer loans or prepaid products) and, from 1 Jul 2024, armoured-car businesses. Dealers in art and auction houses are not named as reporting entities on the FINTRAC guidance opened; dealers in precious metals and stones are a sector under the Act (unconfirmed, U), and a Toronto sale room is therefore outside FINTRAC while the bank that receives its wire is inside.","threshold":"International EFTs of C$10,000 or more (single transaction, or two or more in a static 24-hour window known to share a requester, third party or beneficiary; SWIFT and non-SWIFT aggregated) are reported within 5 business days of initiation or final receipt; domestic transfers are not reported. Foreign currency converted at the Bank of Canada rate on the day. Large cash transactions of C$10,000 or more are reported on the same footing (unconfirmed, U).","asks":"The EFT report carries requester, beneficiary, third-party, account-holder, initiator and receiver names, addresses and identifiers, and source-of-funds fields (how the funds were obtained). The receiving bank in Toronto therefore files the name of the Geneva or Dhaka sender and of the beneficiary on every qualifying wire.","vf":"V","note":"Large Cash Transaction Reports and the full sector list not opened this session.","src":[["FINTRAC, Reporting electronic funds transfers to FINTRAC (issued 29 Feb 2024, modified 24 Jun 2024)","https://fintrac-canafe.canada.ca/guidance-directives/transaction-operation/eft-dt/eft-dt-eng"]]},"sanctions":{"rule":"Special Economic Measures (Russia) Regulations as amended by SOR/2022-102 (registered 18 May 2022, published 8 Jun 2022, luxury-goods bans effective 60 days after coming into force): s.3.8(1) bars any person in Canada or Canadian abroad from exporting, selling, supplying or shipping Schedule 6 Part 1 luxury goods to Russia or anyone in Russia; items 239–257 cover HS 97.01–97.06 — paintings, drawings and pastels, original prints, original sculpture, collages, stamps, collectors’ pieces and antiques, split by age (100 and 250 years), with no value threshold. The import ban (s.3.8(3), Schedule 6 Part 2) covers fish, seafood, caviar, alcohol and diamonds, not art. Personal effects for the traveller’s own use are exempt. s.5 bars facilitation. Penalties under s.8 SEMA: summary up to C$25,000 and/or one year; indictment up to five years. RCMP and CBSA enforce. Dealing prohibitions with the listed persons in Schedule 1 apply to any sale (unconfirmed, U).","vf":"V","src":[["Canada Gazette Part II, SOR/2022-102, 8 Jun 2022","https://gazette.gc.ca/rp-pr/p2/2022/2022-06-08/html/sor-dors102-eng.html"]]},"apost":{"hague":true,"docs":"Canada acceded on 12 May 2023; in force 11 Jan 2024. Before that, Canadian documents were authenticated and then legalised at the receiving state’s consulate.","authority":"Global Affairs Canada (federal documents) and the provincial authorities of Ontario, Quebec, British Columbia, Alberta and Saskatchewan for documents notarised there — unconfirmed (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES; the Wild Animal and Plant Protection and Regulation of International and Interprovincial Trade Act (WAPPRIITA) requires permits from Environment and Climate Change Canada for ivory, tortoiseshell and other listed material in a work; Canada banned elephant-ivory and rhino-horn trade in Jan 2024 (unconfirmed, U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"No art freeport. Bonded warehouses and the CBSA’s customs bonded warehouse programme defer duty (nil for art) and GST until release (U).","vf":"U","src":[]},"capital":{"rule":"No exchange control. A resident may move any sum abroad to buy a work of art and a non-resident may repatriate sale proceeds freely; the controls are reporting, not permission: the bank files an EFT report with FINTRAC for international transfers of C$10,000 or more; the Canada Revenue Agency receives the same international EFT data under the Income Tax Act (unconfirmed, U); foreign property costing over C$100,000 is reported on form T1135 (unconfirmed, U). A cash sum arriving from Dhaka is therefore lawful in Toronto only if it left Bangladesh with Bangladesh Bank’s permission; the Canadian bank will ask for the source of funds and file the EFT report, and if the story does not hold it files a suspicious transaction report.","limits":"No limits. Reporting at C$10,000 (EFT, large cash) within 5 business days; no threshold for a suspicious transaction report.","routes":"Any lawful route through a financial entity; the bank’s own KYC and source-of-funds questions apply. A loan from a Canadian bank against a work stored in Geneva is possible in principle, with the collateral’s title, appraisal and insurance papers (U).","vf":"V","note":"Absence of exchange control is carried unconfirmed; no official page states the negative.","src":[["FINTRAC, Reporting electronic funds transfers to FINTRAC","https://fintrac-canafe.canada.ca/guidance-directives/transaction-operation/eft-dt/eft-dt-eng"]]}},"ar":{"n":"Argentina","exp":{"law":"Law 24,633 of 1996 on the international circulation of works of art (regulated by Decree 1321/97) and Law 25,197 on the register of cultural heritage: works by living artists, or by artists dead less than 50 years, leave freely on a sworn declaration (‘licencia de exportación’ issued by the Ministry of Culture’s Dirección Nacional de Bienes y Sitios Culturales); older works need the Ministry’s authorisation, which it may refuse for heritage of national interest; archaeological and palaeontological objects are barred under Law 25,743 (2003). All unconfirmed (U).","authority":"Ministerio de Cultura (Dirección Nacional de Bienes y Sitios Culturales); Dirección General de Aduanas (ARCA, formerly AFIP).","fee":"Not established.","time":"Not established.","temporary":"Argentina accepts ATA carnets (Cámara Argentina de Comercio is the guaranteeing body) — unconfirmed (U).","treasure":"Archaeological and palaeontological finds belong to the State (Law 25,743) (U).","vf":"U","note":"No Argentine heritage or customs page opened this session.","src":[],"none":false,"needsText":"The export licence or sworn declaration, a photograph and description of the work, and the customs export declaration (U).","needs":[]},"imp":{"duty":"Law 24,633 sets the import duty on works of art at 0% and exempts them from the statistics tax (unconfirmed, U).","vat":"21% VAT applies at import (U).","special":"Works imported for public museums or exhibitions are relieved (U).","state_tax":"Gross-receipts taxes at provincial level on dealers, not on the importer (U).","overlays":"Argentina’s ‘PAIS’ tax on foreign-currency purchases lapsed in Dec 2024 and the 30% ‘percepción’ on individuals’ foreign-currency purchases was eliminated by ARCA General Resolution 5672/2025 in Apr 2025 (EY).","cpia":"Argentina is a party to the 1970 UNESCO Convention (U).","vf":"U","note":"Duty and VAT unconfirmed; only the tax-on-currency point was read.","vat_rate":0.21,"duty_rate":0,"src":[["EY Global Tax News, Argentina relaxes foreign exchange restrictions (BCRA Communication A 8226), 15 Apr 2025","https://globaltaxnews.ey.com/news/2025-0896"]]},"aml":{"rule":"Law 25,246 (1999, amended) and the Unidad de Información Financiera (UIF). Dealers in works of art, antiques and collectors’ items are ‘sujetos obligados’ under UIF resolutions and must register, identify customers and report suspicious operations — unconfirmed (U).","threshold":"Customer identification and reporting thresholds set by UIF resolution in pesos, revised yearly (figures not opened, U).","asks":"ID, tax number (CUIT/CUIL), declared source of funds and PEP status (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"sanctions":{"rule":"Argentina applies UN Security Council sanctions through decrees; it has no autonomous Russia or Belarus sanctions and does not apply the EU or US luxury-goods bans (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":true,"docs":"Argentina acceded on 8 May 1987; in force 18 Feb 1988.","authority":"Ministerio de Relaciones Exteriores and the Colegios de Escribanos (notaries’ colleges) by delegation — unconfirmed (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1981; permits from the Dirección Nacional de Biodiversidad under Law 22,421 (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"No art freeport; the Tierra del Fuego and La Plata free zones are industrial (U).","vf":"U","src":[]},"capital":{"rule":"The ‘cepo’ for individuals ended on 14 Apr 2025: BCRA Communication ‘A’ 8226 (11 Apr 2025) gives individuals access to the official exchange market to buy foreign currency without prior BCRA authorisation (the $200 monthly cap of 2019 is gone) and ARCA Resolution 5672/2025 removed the 30% withholding on those purchases; Decree 269/2025 repealed the 80/20 export-settlement split. Companies still cannot buy foreign currency to hold; they may pay dividends abroad only from earnings of fiscal years beginning on or after 1 Jan 2025, pay imports without the former 30-day wait, pay unrelated-party services on accrual and related-party services after 90 days. Communications ‘A’ 8330 and 8331 (18 Sept 2025) removed the $36,000 annual limit for individuals keeping service-export proceeds in foreign currency, barred bank commissions on inflows to residents and let non-residents access the market to repatriate direct investments made to buy local companies. A resident individual may therefore buy dollars and wire them abroad to buy a work of art; the bank still applies AML checks and the cross-restriction with securities (90-day ‘parking’) and sworn statements carried unconfirmed (U). Non-residents repatriating portfolio investments or sale proceeds: subject to BCRA rules and minimum holding periods not opened this session (U).","limits":"Individuals: no quantitative limit since 14 Apr 2025 (EY; Marval). Companies: no purchase for hoarding; dividends only from 2025 earnings (EY). Export proceeds for certain fuels: 180 days to settle (Marval).","routes":"An individual’s own purchase of foreign currency in the official market and transfer abroad; a non-resident’s repatriation of a direct investment under ‘A’ 8331; documented export earnings. Press of Nov 2025 reported the government’s intention to lift the remaining corporate restrictions ‘soon’ (headline only, not opened, U); as of 9 Nov 2026 no later communication was read.","vf":"S","note":"BCRA’s own communications were not opened; the EY and Marval summaries were. The state after Oct 2025 is not confirmed.","src":[["EY Global Tax News, Argentina relaxes foreign exchange restrictions, 15 Apr 2025","https://globaltaxnews.ey.com/news/2025-0896"],["Marval O’Farrell Mairal, Foreign exchange restrictions relaxed (Communications A 8330 and A 8331), 28 Oct 2025","https://www.marval.com/Publicacion/se-flexibilizan-las-restricciones-cambiarias-17372?lang=en"]]}},"eg":{"n":"Egypt","exp":{"law":"Antiquities Protection Law 117 of 1983 (amended by Laws 3/2010 and 91/2018): antiquities (objects of 100 years or more of archaeological, artistic or historical value) are State property and may not be exported; trading in them is a crime. Works of art under 100 years old leave with a certificate from the Ministry of Culture (Fine Arts Sector) that the object is not an antiquity, which customs demands for paintings and sculpture — unconfirmed (U).","authority":"Supreme Council of Antiquities (Ministry of Tourism and Antiquities); Ministry of Culture Fine Arts Sector; Egyptian Customs Authority.","fee":"Not established.","time":"Not established.","temporary":"Egypt is not an ATA carnet country (U); temporary export of antiquities for exhibition needs a Cabinet-level decision under Law 117 (U).","treasure":"All antiquities found on or in Egyptian land belong to the State (Law 117 art. 6) (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[],"none":false,"needsText":"Ministry of Culture / Supreme Council of Antiquities clearance that the object is not an antiquity; customs export declaration (U).","needs":[]},"imp":{"duty":"Customs duty on chapter 97 works of art (rate not confirmed; 30% recalled for 9701, U).","vat":"14% VAT at import (U).","special":"Imports for public museums relieved (U).","state_tax":"None.","overlays":"Egypt’s customs law 207/2020 and the ACI pre-registration system apply to every import (U).","cpia":"Party to the 1970 UNESCO Convention (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","vat_rate":0.14,"duty_rate":0,"src":[]},"aml":{"rule":"Anti-Money Laundering Law 80 of 2002 (amended) and the Egyptian Money Laundering and Terrorist Financing Combating Unit (EMLCU) at the Central Bank. Obliged persons are banks, exchange companies, money transfer firms, securities and insurance; dealers in precious metals and stones and real-estate brokers were added by executive regulation; art dealers are not obliged (U).","threshold":"Cash declaration at the border above $10,000 equivalent (U); banks’ cash reporting thresholds set by EMLCU (U).","asks":"National ID or passport, source of funds for transfers abroad (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"sanctions":{"rule":"UN Security Council lists applied through the National Committee; no autonomous Russia sanctions (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":false,"docs":"Egypt does not appear in the HCCH status table of 130 Contracting Parties (read 9 Nov 2026).","authority":"Not a Contracting Party: documents are authenticated by the Egyptian Ministry of Foreign Affairs and then legalised at the receiving state’s consulate (and foreign documents at the Egyptian consulate abroad, then the MFA in Cairo) — route unconfirmed (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1978; the Egyptian Environmental Affairs Agency issues permits; ivory trade banned (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"Public free zones (Nasr City, Alexandria, Port Said, Suez, Damietta) are industrial and trading zones under GAFI; no art freeport (U).","vf":"U","src":[]},"capital":{"rule":"Formal controls were dismantled in 2017: the $100,000 annual cap on individuals’ foreign-currency transfers abroad imposed after 2011 was lifted in June 2017, and on 28 Nov 2017 the Central Bank of Egypt removed the 2015 caps on importers’ cash deposits ($10,000 a day, $50,000 a month) and withdrawals ($30,000), described as its ‘last remaining official foreign-currency controls’. In the dollar shortage of 2022–Mar 2024 banks rationed foreign currency informally, capped card spending abroad and queued transfers; the 6 Mar 2024 flotation and the IMF and Ras El-Hekma inflows cleared the backlog (unconfirmed, U). As of 2026 a resident may buy foreign currency from a bank and transfer it abroad for a documented purpose, subject to the bank’s AML checks and the CBE’s instructions on the purpose of transfer; the current instructions were not opened (U). Non-residents and foreign investors may repatriate capital, profits and sale proceeds in foreign currency under the Investment Law 72 of 2017, through the bank that recorded the inflow (U).","limits":"No published quantitative limit found since 2017; banks apply their own card and transfer ceilings (U).","routes":"Documented purchase through a bank; a non-resident’s own funds recorded on arrival; inheritance and gifts through a bank with documents (U).","vf":"S","note":"Only the 2017 report was opened; the 2022–24 episode and the 2026 state are unconfirmed.","src":[["Capital Markets in Africa (Bloomberg syndication), Egypt lifts remaining currency restrictions as crunch abates, 28 Nov 2017","https://www.capitalmarketsinafrica.com/egypt-lifts-remaining-currency-restrictions-as-crunch-abates/"]]}},"ng":{"n":"Nigeria","exp":{"law":"National Commission for Museums and Monuments Act (Decree 77 of 1979, Cap N19 LFN 2004): no antiquity may be exported without a permit from the Commission; ‘antiquity’ covers objects made before 1918 and ethnographic objects used in traditional ceremonies. Contemporary art needs the Commission’s export certificate confirming the object is not an antiquity, which customs asks for — unconfirmed (U).","authority":"National Commission for Museums and Monuments; Nigeria Customs Service.","fee":"Not established.","time":"Not established.","temporary":"Nigeria is not in the ATA carnet chain (U).","treasure":"Antiquities discovered are notified to the Commission, which may acquire them (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[],"none":false,"needsText":"NCMM export permit or non-antiquity certificate; Nigeria Customs Service export declaration (U).","needs":[]},"imp":{"duty":"ECOWAS Common External Tariff: chapter 97 works of art at 20% (band 4, ‘final consumer goods’) — unconfirmed (U).","vat":"7.5% VAT at import (U).","special":"Not found.","state_tax":"None.","overlays":"ECOWAS levy, port and inspection charges; import duty is paid in naira at the CBN rate (U).","cpia":"Party to the 1970 UNESCO Convention (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","vat_rate":0.075,"duty_rate":0,"src":[]},"aml":{"rule":"Money Laundering (Prevention and Prohibition) Act 2022 (assented 13 May 2022, repealing the 2011 Act). Cash payments above N5,000,000 (individuals) and N10,000,000 (bodies corporate) are prohibited except through a financial institution; transactions above those sums are disclosed; transfers to or from abroad above $10,000 are reported to the Nigerian Financial Intelligence Unit (and the SEC); cash or negotiable instruments above $10,000 are declared to the Nigeria Customs Service. Designated non-financial businesses are supervised by the Special Control Unit against Money Laundering (SCUML), which may suspend a licence and fine up to N1,000,000; the Act’s DNFBP list includes dealers in jewellery, cars and luxury goods, precious metals and stones, real estate, hotels, casinos and supermarkets (list unconfirmed, U) — an art dealer registers with SCUML as a dealer in luxury goods in practice (U). Nigeria was removed from the FATF grey list in Oct 2025 (unconfirmed, U).","threshold":"N5,000,000 (individuals) and N10,000,000 (corporate) for cash; $10,000 for international transfers and cash declarations.","asks":"Bank verification number, ID, source of funds, SCUML registration certificate for DNFBP accounts (U).","vf":"S","src":[["PwC Nigeria, Regulatory alert: an overview of the Money Laundering (Prevention and Prohibition) Act 2022","https://pwc.com/ng/en/assets/pdf/regulatory-alert-an-overview-of-the-money-laundering-act-2022.pdf"]]},"sanctions":{"rule":"Terrorism (Prevention and Prohibition) Act 2022 and the Nigeria Sanctions Committee apply the UN lists and a national list; no autonomous Russia sanctions (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":false,"docs":"Nigeria does not appear in the HCCH status table (read 9 Nov 2026).","authority":"Not a Contracting Party: authentication by the Federal Ministry of Foreign Affairs, then legalisation at the receiving state’s mission (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1975; Endangered Species (Control of International Trade and Traffic) Act, amended 2016; permits from the Federal Ministry of Environment (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"Lekki and other free zones under NEPZA are industrial; no art freeport (U).","vf":"U","src":[]},"capital":{"rule":"Foreign Exchange (Monitoring and Miscellaneous Provisions) Act 1995 and the CBN Foreign Exchange Manual: residents may hold domiciliary accounts and buy foreign exchange from banks for ‘invisible’ transactions on Form A (travel, education, medical, subscriptions) within documented limits; a transfer abroad to buy an asset for investment is a capital transaction that needs CBN approval through the bank, and the CBN has since 2015 excluded a list of items from the official window (unconfirmed, U). Since the June 2023 unification and the 2024–25 reforms banks sell foreign currency at market rates, but the documentary rules stand (U). A non-resident who brought capital in through a bank with a Certificate of Capital Importation (CCI) may repatriate capital, dividends and sale proceeds through the same bank at the market rate (U). The 2022 Act adds the $10,000 international-transfer report to the NFIU and the cash declaration at the border (PwC).","limits":"Form A limits are set per purpose by CBN circular (not opened, U); international transfers above $10,000 are reported (PwC).","routes":"Form A invisible transactions; CBN-approved capital transfers; a non-resident’s CCI; documented export proceeds in a domiciliary account (U).","vf":"U","note":"No CBN page opened; only the AML reporting thresholds were read.","src":[["PwC Nigeria, Regulatory alert on the Money Laundering (Prevention and Prohibition) Act 2022","https://pwc.com/ng/en/assets/pdf/regulatory-alert-an-overview-of-the-money-laundering-act-2022.pdf"]]}},"pk":{"n":"Pakistan","exp":{"law":"Antiquities Act 1975 (federal; provincial acts since the 18th Amendment, e.g. Punjab 2012, Sindh 1994): no antiquity may be exported without a licence from the Director General of Archaeology; ‘antiquity’ includes objects at least 75 years old of historical or artistic interest. Contemporary art leaves on a customs export declaration, often with a Department of Archaeology certificate that the object is not an antiquity — unconfirmed (U).","authority":"Department of Archaeology and Museums (federal) and provincial departments; Pakistan Customs (FBR).","fee":"Not established.","time":"Not established.","temporary":"Pakistan is not an ATA carnet country (U).","treasure":"Antiquities found belong to the Government (1975 Act) (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[],"none":false,"needsText":"Non-antiquity certificate or export licence; customs declaration (U).","needs":[]},"imp":{"duty":"Customs duty on chapter 97 under the Pakistan Customs Tariff (rate not confirmed; 20% recalled, U) plus additional customs duty.","vat":"18% sales tax at import (U).","special":"Not found.","state_tax":"None.","overlays":"Regulatory duty and withholding income tax at import apply to many consumer goods (U).","cpia":"Party to the 1970 UNESCO Convention (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","vat_rate":0.18,"duty_rate":0,"src":[]},"aml":{"rule":"Anti-Money Laundering Act 2010 (amended 2020) and the Financial Monitoring Unit. DNFBPs regulated since 2020 are real-estate agents, dealers in precious metals and stones, lawyers, accountants and trust and company service providers; art dealers are not covered (U). Pakistan left the FATF grey list in Oct 2022 (U).","threshold":"Currency transaction reports at PKR 2,000,000 (U).","asks":"CNIC, source of funds, tax status (filer or non-filer) (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"sanctions":{"rule":"UN lists under the United Nations (Security Council) Act 1948; no autonomous Russia sanctions (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":true,"docs":"Pakistan acceded on 8 Jul 2022; in force 9 Mar 2023 (accession A**, with non-objecting Contracting Parties).","authority":"Ministry of Foreign Affairs (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1976; permits from the Ministry of Climate Change (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"No art freeport; export processing zones only (U).","vf":"U","src":[]},"capital":{"rule":"Foreign Exchange Regulation Act 1947 (Pakistan’s own, the same 1947 statute as Bangladesh’s) and the State Bank of Pakistan’s Foreign Exchange Manual: a resident may not transfer capital abroad or acquire foreign assets without SBP permission through an authorised dealer; the manual lists the permitted current-account remittances. SBP’s 2021 liberalisation (press report, date on the page not shown) let resident individuals invest in listed securities abroad without approval up to $25,000 per calendar year (holding under 1% of the investee), employees of foreign-owned subsidiaries remit up to $50,000 a year into parent share plans, export firms set up offices abroad with up to 10% of three-year average export earnings or $100,000, and start-ups form holding companies abroad; ‘residents would need to approach SBP for approval through their banks as per existing policy’ for everything else. Buying a work of art abroad is not within any of these windows and needs SBP’s approval (U). Exchange companies’ sales of foreign currency to individuals are capped by SBP (a $100,000 per person per year ceiling appears in a 2023 Business Recorder headline not opened, U). Non-residents repatriate registered investment and its proceeds through the bank that recorded it; Roshan Digital Accounts give non-resident Pakistanis full repatriability (U).","limits":"$25,000 a year for listed foreign securities; $50,000 for share-option plans; $100,000 or 10% of export earnings for an export office (The News, 2021). All other capital transfers: SBP approval.","routes":"The listed-securities window; export earnings; a non-resident’s own documented inflows; SBP special permission.","vf":"S","note":"SBP’s own press release and FAQ redirected to the home page; the press summary was read instead.","src":[["The News (Pakistan), SBP exempts resident investors from approval for foreign investment (2021)","https://thenews.com.pk/print/788097-sbp-exempts-resident-investors-from-approval-for-foreign-investment"]]}},"tr":{"n":"Turkey","exp":{"law":"Law 2863 of 1983 on the Protection of Cultural and Natural Property: movable cultural property may not be taken abroad; a work of art that is not cultural property (in practice, work by living artists or of the last century that a state museum certifies as not protected) may leave with the museum directorate’s certificate, which customs requires for any painting, icon, carpet or antique — unconfirmed (U).","authority":"Ministry of Culture and Tourism, General Directorate of Cultural Heritage and Museums; Ministry of Trade (customs).","fee":"Not established.","time":"Not established.","temporary":"Turkey accepts ATA carnets (TOBB is the guaranteeing body) (U).","treasure":"Finds belong to the State; finders are rewarded under Law 2863 (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[],"none":false,"needsText":"Museum directorate (Ministry of Culture and Tourism) certificate; customs export declaration (U).","needs":[]},"imp":{"duty":"0% under the EU–Turkey customs union for chapter 97 originals (U).","vat":"Standard VAT 20% since 10 Jul 2023 (U); the rate applied to works of art at import was not confirmed (U).","special":"Not found.","state_tax":"None.","overlays":"None found.","cpia":"Party to the 1970 UNESCO Convention (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","vat_rate":0.2,"duty_rate":0,"src":[]},"aml":{"rule":"Law 5549 (2006) and MASAK. Obliged parties include banks, exchange offices, jewellers, dealers in precious metals and stones, real-estate agents, notaries, lawyers, and — under the 2008 regulation — those who trade in or broker ‘antiques and works of art’ (unconfirmed, U).","threshold":"Customer identification at TRY thresholds revised yearly; suspicious-transaction reporting without threshold (U).","asks":"ID, tax number, address; PEP and sanctions screening (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"sanctions":{"rule":"Turkey applies UN sanctions only; it has not adopted the EU, UK or US sanctions on Russia or their luxury-goods bans, though Turkish banks have curtailed Russian payments since 2023 under US secondary-sanctions pressure (unconfirmed, U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":true,"docs":"Turkey ratified on 31 Jul 1985; in force 29 Sept 1985.","authority":"Governorships (valilik) and district governorships for administrative documents; heavy penal courts’ justice commissions for judicial documents (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1996; permits from the Ministry of Agriculture and Forestry (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"Free zones (Istanbul Atatürk Airport, Mersin, Ege) are industrial; no dedicated art freeport (U).","vf":"U","src":[]},"capital":{"rule":"Decree No. 32 on the Protection of the Value of Turkish Currency (1989) made the lira convertible: residents may hold foreign currency and transfer it abroad freely through banks, including to buy assets abroad, and non-residents may repatriate capital and proceeds freely; banks report transfers to MASAK and the Central Bank under the AML and statistical rules, and the identity of the sender and purpose is recorded (unconfirmed, U). The 2018 ban on foreign-currency-indexed contracts between residents and the 2022–23 measures nudging exporters to convert part of their proceeds did not restrict individuals’ outward transfers (U).","limits":"No quantitative limit for residents or non-residents (U).","routes":"Any bank transfer with purpose stated; cash above EUR 10,000 equivalent is declared at the border (U).","vf":"U","note":"No Turkish source opened this session; all unconfirmed.","src":[]}},"id":{"n":"Indonesia","exp":{"law":"Law 11 of 2010 on Cultural Conservation (Cagar Budaya): registered or registrable cultural-heritage objects may not be taken abroad without the Minister’s permit; contemporary art leaves on an ordinary export declaration (U).","authority":"Ministry of Culture (Direktorat Jenderal Kebudayaan); Directorate General of Customs and Excise.","fee":"Not established.","time":"Not established.","temporary":"Indonesia accepts ATA carnets since 2015 (KADIN) (U).","treasure":"Finds are reported to the State (Law 11/2010) (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[],"none":false,"needsText":"Customs export declaration; for anything that may be cagar budaya, the Ministry of Culture’s permit (U).","needs":[]},"imp":{"duty":"Chapter 97 at 0–5% under the Indonesian tariff (not confirmed, U).","vat":"11% VAT at import; the 12% rate from 1 Jan 2025 applies only to luxury goods subject to luxury sales tax (U).","special":"Not found.","state_tax":"None.","overlays":"Import income tax (PPh 22) at 2.5–10% on the import value is prepaid (U).","cpia":"Not a party to the 1970 UNESCO Convention (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","vat_rate":0.11,"duty_rate":0,"src":[]},"aml":{"rule":"Law 8 of 2010 and PPATK. Government Regulation 43 of 2015 lists as reporting parties property companies, motor-vehicle dealers, dealers in jewellery and precious metals, dealers in art and antiques, and auction houses, which must identify customers and report cash and suspicious transactions — unconfirmed (U).","threshold":"Cash transaction reports at IDR 500,000,000 (U).","asks":"KTP or passport, NPWP tax number, source of funds (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"sanctions":{"rule":"UN lists applied through the DTTOT and proliferation lists; no autonomous Russia sanctions (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":true,"docs":"Indonesia acceded on 5 Oct 2021; in force 4 Jun 2022.","authority":"Ministry of Law (Directorate General of General Legal Administration, AHU) (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1978; permits from the Ministry of Forestry (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"Batam, Bintan and Karimun free-trade zones are industrial; no art freeport (U).","vf":"U","src":[]},"capital":{"rule":"Law 24 of 1999 on foreign-exchange flows keeps a free regime: residents may hold and transfer foreign currency abroad, and non-residents may repatriate, through banks that report to Bank Indonesia (U). The constraint is on buying foreign currency with rupiah: under Bank Indonesia Regulation 24/7/PBI/2022 and Board of Governors Regulation 24/10/PADG/2022 a customer may buy foreign currency against rupiah without underlying documents up to $100,000 or equivalent per month; above that the bank requires underlying transaction documents (a contract or invoice), and the purchase must match them (Bank BCA summary, 2022; a sworn statement below the threshold and a $25,000 threshold for some transaction types are unconfirmed, U). Rupiah may not be transferred abroad (PBI 18/19/2016, U). A resident who wants to pay $500,000 for a painting abroad therefore shows the bank the invoice as the underlying document; without it the purchase is capped at $100,000 a month.","limits":"$100,000 per month per customer without underlying documents (BCA, citing PBI 24/7/PBI/2022).","routes":"Purchase against documents; foreign-currency balances already held; a non-resident’s own funds; documented export earnings.","vf":"S","note":"Bank Indonesia’s own regulation page not opened; a bank’s customer notice was.","src":[["Bank BCA, Information on the threshold for foreign-exchange transactions (PBI 24/7/PBI/2022), 15 Jul 2022","https://www.bca.co.id/en/informasi/news-and-features/2022/07/15/02/49/informasi-ketentuan-threshold-transaksi-valas"]]}},"vn":{"n":"Vietnam","exp":{"law":"Law on Cultural Heritage 45/2024/QH15 (effective 1 Jul 2025, replacing the 2001/2009 law) and Decree 32/2012 on the export and import of cultural products: relics, antiques (100 years or more) and national treasures may not be exported except for exhibition with a permit; works of art leave with a Ministry of Culture, Sports and Tourism appraisal that they are not antiques, and the customs export declaration — unconfirmed (U).","authority":"Ministry of Culture, Sports and Tourism; General Department of Vietnam Customs.","fee":"Not established.","time":"Not established.","temporary":"Vietnam is not in the ATA carnet chain (U).","treasure":"Finds belong to the State (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[],"none":false,"needsText":"Provincial Department of Culture appraisal certificate for anything that could be an antique; customs declaration (U).","needs":[]},"imp":{"duty":"Chapter 97 at 0–10% (not confirmed, U); imported cultural products are subject to Ministry of Culture content appraisal under Decree 32/2012 (U).","vat":"10% VAT; the temporary 8% rate extended through 2026 excludes some goods (U).","special":"Not found.","state_tax":"None.","overlays":"None found.","cpia":"Party to the 1970 UNESCO Convention (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","vat_rate":0.1,"duty_rate":0,"src":[]},"aml":{"rule":"Anti-Money Laundering Law 14/2022/QH15 (effective 1 Mar 2023) and the State Bank’s AML Department. Reporting entities are banks, insurers, securities firms, real-estate brokers, lawyers, notaries, dealers in precious metals and stones and gaming; art dealers are not listed (U). Vietnam has been on the FATF grey list since Jun 2023 (U).","threshold":"Large-value transaction reports at VND 400,000,000 (Decision 11/2023) (U).","asks":"ID, source of funds and purpose for every outward transfer (Circular 20/2022).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"sanctions":{"rule":"UN lists only; no autonomous Russia sanctions (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":true,"docs":"Viet Nam acceded on 31 Dec 2025; entry into force 11 Sept 2026 (accession A**, so only with Contracting Parties that did not object; the HCCH table was last updated 30 Jun 2026, before that date). For documents going to a state that objected, consular legalisation continues.","authority":"Ministry of Foreign Affairs (Consular Department) (U).","fee":"Not established.","time":"Not established.","vf":"V","note":"Which states, if any, objected was not opened.","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1994; permits from the CITES Management Authority at the Ministry of Agriculture (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"No art freeport; bonded warehouses under the customs law (U).","vf":"U","src":[]},"capital":{"rule":"The Ordinance on Foreign Exchange (2005, amended 2013) and State Bank Circular 20/2022/TT-NHNN (30 Dec 2022, effective 15 Feb 2023) on one-way money transfers abroad: a resident individual may buy, transfer or carry foreign currency abroad only for the listed purposes — study, medical treatment, work, tourism or visits (the LuatVietnam summary) and, from the circular itself as recalled, inheritance, settlement abroad and support for relatives (U) — and the licensed bank checks the documents for each; the sources of funds may be the individual’s foreign-currency accounts, deposits or cash and the bank’s own foreign currency; where the destination has no currency of its own the bank may sell another convertible currency; the bank certifies cash carried above the customs-declaration level. Buying a work of art abroad is not a listed purpose, so a resident has no route for it; residents may not invest abroad without an outward-investment registration certificate from the Ministry of Planning and Investment and a State Bank registration (U). Non-residents and foreign investors repatriate lawful income, capital and sale proceeds through their bank against the investment registration and tax papers (U).","limits":"No fixed sums in the summary read; the bank sets the amount against the documents for each purpose (U).","routes":"The listed personal purposes; registered outward investment; a non-resident’s documented inflows.","vf":"S","note":"The circular’s full text was not opened; the summary names five purposes and no amounts.","src":[["LuatVietnam, Guidance on one-way money transfer abroad from Vietnam (Circular 20/2022/TT-NHNN)","https://english.luatvietnam.vn/legal-updates/guidance-on-one-way-money-transfer-abroad-from-vietnam-892-92779-article.html"]]}},"il":{"n":"Israel","exp":{"law":"Antiquities Law 1978: an antiquity (made before 1700, or a later object of historical value so declared) may not be exported without a permit from the Israel Antiquities Authority; dealers in antiquities are licensed. Works of art are free of export licence (U).","authority":"Israel Antiquities Authority; Israel Tax Authority (customs).","fee":"Not established.","time":"Not established.","temporary":"Israel accepts ATA carnets (Federation of Israeli Chambers of Commerce) (U).","treasure":"Antiquities discovered belong to the State (1978 Law) (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[],"none":false,"needsText":"Customs export declaration; IAA export permit for antiquities (U).","needs":[]},"imp":{"duty":"Chapter 97 works of art free of customs duty (U).","vat":"18% VAT since 1 Jan 2025 (17% before) at import (U).","special":"Museums and recognised institutions relieved (U).","state_tax":"None.","overlays":"Purchase tax does not apply to works of art (U).","cpia":"Not a party to the 1970 UNESCO Convention (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","vat_rate":0.18,"duty_rate":0,"src":[]},"aml":{"rule":"Prohibition on Money Laundering Law 2000 and the Israel Money Laundering and Terror Financing Prohibition Authority (IMPA). Obliged bodies are banks, insurers, portfolio managers, money-service businesses, lawyers and accountants for certain services, and dealers in precious stones (since 2018); art dealers and auction houses are not obliged (U). The Reduction in the Use of Cash Law 2018 caps cash in a transaction with a business at NIS 6,000 (since 1 Aug 2022; NIS 11,000 before) and between private persons at NIS 15,000 (U).","threshold":"Cash caps NIS 6,000 / NIS 15,000; banks report cash transactions above NIS 50,000 and cross-border transfers above a threshold to IMPA (U).","asks":"ID, declared beneficiary and source of funds; banks question foreign-source deposits closely (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"sanctions":{"rule":"Counter-Terrorism Law 2016 designations and the UN lists; Israel has not adopted the EU, UK or US sanctions on Russia, though Israeli banks apply them in dollar and euro business (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"apost":{"hague":true,"docs":"Israel acceded on 11 Nov 1977; in force 14 Aug 1978.","authority":"Ministry of Foreign Affairs for public documents; the courts’ registrars for notarised documents (U).","fee":"Not established.","time":"Not established.","vf":"V","src":[["HCCH status table, Apostille Convention (read 9 Nov 2026)","https://www.hcch.net/en/instruments/conventions/status-table?cid=41"]]},"cites":{"rule":"Party to CITES since 1980; permits from the Israel Nature and Parks Authority (U).","vf":"U","note":"No page opened for this cell this session; carried unconfirmed.","src":[]},"freeport":{"rule":"No art freeport; the Eilat free-trade zone is a VAT-free retail area (U).","vf":"U","src":[]},"capital":{"rule":"No exchange control: the liberalisation begun in 1998 was completed in 2003, and residents may transfer any sum abroad to buy assets while non-residents repatriate freely; banks apply AML identification and report to IMPA, and the bank’s ‘source of funds’ questions are the practical gate (unconfirmed, U). Tax: Israeli residents report foreign assets and income; a 2024–25 reform taxes certain foreign-source income of new immigrants from 2026 (U).","limits":"None (U).","routes":"Any bank transfer with declared purpose (U).","vf":"U","note":"No Israeli source opened this session; all unconfirmed.","src":[]}}};
const NAV_EU={"n":"European Union (applies to FR, DE, IT, NL, ES)","members":["fr","de","it","nl","es"],"exp":{"law":"Council Regulation (EC) No 116/2009 on the export of cultural goods (codified); Implementing Regulation (EU) No 1081/2012. A licence is needed to export listed goods outside the EU customs territory; it is issued by the Member State where the object is lawfully and definitively located (Art 2(2)).","authority":"Competent authority of the Member State (e.g. ministries of culture); value assessed at the date of application.","fee":"Set nationally.","time":"Set nationally.","temporary":"Temporary and open licences exist under the implementing regulation (not opened).","treasure":"National ‘treasure’ regimes sit alongside: a national licence may be refused even where the EU licence would be due.","eu_licence":"The EU licence only governs exit from the EU customs territory; movements between Member States are governed by national rules (e.g. DE, FR, IT thresholds).","vf":"V","src":[["Regulation 116/2009 Annex I (legislation.gov.uk copy, 31 Jan 2020)","https://www.legislation.gov.uk/eur/2009/116/annex/I/2020-01-31"]],"none":false,"needs":[{"cat":"painting","age":50,"value":150000.0,"cur":"eur","note":"A.3: pictures and paintings executed entirely by hand, over 50 years old and not belonging to their originators."},{"cat":"sculpture","age":50,"value":50000.0,"cur":"eur","note":"A.7: original sculptures or statuary and copies by the same process."},{"cat":"paper","age":50,"value":15000.0,"cur":"eur","note":"A.5 drawings and hand-executed mosaics €15,000; A.4 watercolours, gouaches, pastels €30,000. A.6: original engravings, prints, serigraphs, lithographs, posters.","lowest":true},{"cat":"photo","age":50,"value":15000.0,"cur":"eur","note":"A.8: photographs, films and negatives."},{"cat":"design","age":50,"value":50000.0,"cur":"eur","note":"A.15 other antiques 50–100 years (listed types) or over 100 years; archaeology and monument parts over 100 years, manuscripts, archives over 50 years: whatever the value; books over 100 years €50,000; maps over 200 years €15,000."}]},"imp":{"duty":"0% erga omnes on chapter 97 (seen for 9705 10 00 on a TARIC mirror).","vat":"Rates national (FR 5.5%, DE 7%, IT 5%, NL 9%, ES 10%); Directive 2022/542 allows reduced rates on art supplies but bars combining them with the margin scheme.","icg":"Regulation (EU) 2019/880 applies since 28 June 2025. Part B (import licence): archaeological objects and dismembered parts of monuments over 250 years old, any value. Part C (importer statement): other listed goods over 200 years old and worth over €18,000 per item. Both filed in the central ICG system (EU CSW-CERTEX). ‘Import’ includes free circulation, customs warehousing, free zones, temporary admission, end-use and inward processing. Exemptions: returned goods; educational/scientific use. Licence decisions within 90 days.","special":"Implementing Regulation (EU) 2021/1079 sets formats and exemptions. Works created in the EU are outside the scope (recital; not opened). A document declared under the wrong customs procedure causes rejection.","vf":"V","duty_rate":0,"src":[["European Commission Access2Markets, new import controls on cultural goods","https://trade.ec.europa.eu/access-to-markets/en/news/eu-introduces-new-import-controls-cultural-goods"],["BAK fact sheet on Reg 2019/880 (11 Jul 2025)","https://www.bak.admin.ch/dam/bak/en/dokumente/kulturguetertransfer/merkblatt_hinweis/Faktenblatt%20EU%20Einfuhrverordnung%2020197-880-stand%2011.07.2025.pdf.download.pdf/Faktenblatt%20EU%20Einfuhrverordnung%2020197-880-stand%2011.07.2025.pdf"],["TARIC 9705 10 00 mirror","https://www.thetradehub.eu/en/customs/taric/97051000"]]},"aml":{"rule":"Regulation (EU) 2024/1624 (AMLR), applying from 10 July 2027: obliged entities include persons trading in or intermediating cultural goods (galleries, auction houses) and persons storing, trading or intermediating cultural goods and other high-value goods in free zones and customs warehouses, for transactions of at least €10,000 (Art 3(3)(i),(j)); ‘cultural goods’ = Annex I of Reg 116/2009. EU-wide cash limit €10,000; occasional-transaction CDD at €10,000 (€3,000 cash). AMLA (Frankfurt) supervises from 2025/2028 (not opened). Until then AMLD5 national rules apply.","threshold":"€10,000","asks":"Customer identification and verification, beneficial owner (25% rule, unconfirmed), purpose of the business relationship, source of funds on a risk basis.","vf":"V","src":[["NRW Finanzverwaltung note on Reg 2024/1624 obliged entities","https://www.finanzverwaltung.nrw.de/system/files/media/document/file/eu-aml-vo-erstinfo-verpflichtete_kunsthaendler-kunst-lagerhalter-kunstvermittler.pdf"],["Regulation (EU) 2024/1624, OJ L 19 Jun 2024 (recitals read)","https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=OJ%3AL_202401624"]]},"sanctions":{"rule":"Regulation 833/2014 Art 3h: ban on selling, supplying, transferring or exporting Annex XVIII luxury goods (incl. works of art, chapter 97) to any person in Russia or for use in Russia, where the value exceeds €300 per item unless otherwise specified; since Dec 2023 regardless of origin; brokering and financing also banned. Belarus: similar restriction since June 2024. Art 5b: no deposits over €100,000 per credit institution from Russian nationals/residents or Russian entities (EU/EEA/Swiss nationals and residence-permit holders excepted). No EU import ban specific to Russian-origin art found.","vf":"S","src":[["K&L Gates, EU and UK luxury goods sanctions, 8 Aug 2024","https://www.klgates.com/The-Impact-of-the-EU-and-UK-Russian-Sanctions-Regime-on-the-Luxury-Goods-Sector-8-8-2024"],["Art 5b Reg 833/2014 (gesetze.legal text)","https://gesetze.legal/eu/vo_eu_2014_833/5b"]]},"cites":{"rule":"Regulation (EC) 338/97 (wildlife trade). Ivory: from 19 Jan 2022 (Commission Reg 2021/2280 and revised guidance) Member States should not issue import permits or re-export certificates for ivory for commercial purposes, except pre-1947 items sold to museums and pre-1975 musical instruments; intra-EU sale of worked ivory only with a commercial certificate proving manufacture before 1947; no percentage de minimis. Tortoiseshell, rosewood (Dalbergia, Annex B) and coral: permit regime not opened.","vf":"S","src":[["BADA, EU ivory rules from 19 Jan 2022","https://www.bada.org/resources/eu-commissions-recommendation-ivory-importexport-prohibition-starts-19-january-2022"]]},"freeport":{"rule":"Reg 2024/1624 brings operators storing or trading cultural and high-value goods in free zones and customs warehouses within AML duties from 10 July 2027; AMLD5 already covers freeport operators (UK and EU transpositions). Luxembourg’s Le Freeport (Findel): press titles seen suggest conversion to a ‘Luxembourg High Security Hub’ / defence depot, but no page could be opened; status in 2026 unconfirmed.","vf":"U","src":[["NRW note on Reg 2024/1624","https://www.finanzverwaltung.nrw.de/system/files/media/document/file/eu-aml-vo-erstinfo-verpflichtete_kunsthaendler-kunst-lagerhalter-kunstvermittler.pdf"]]}};
const NAV_FEES={"condition":{"n":"Condition report","lo":400,"hi":1500,"vf":"U","src":[],"note":"a conservator’s written report with photographs; more for a large or fragile work"},"authentication":{"n":"Authentication","lo":0,"hi":5000,"vf":"U","src":[],"note":"foundations and catalogue raisonné committees charge from nothing to several thousand dollars; some have closed (Warhol, Basquiat, Pollock-Krasner)"},"crate":{"n":"Museum-grade crate","lo":700,"hi":2400,"vf":"S","src":[["FairArt, shipping fine art: export crates, insurance (playbook)","https://fairart.com/editorial/insights/shipping-fine-art-export-crates-insurance-playbook/242"]],"note":"single-wall $700–1,400 (works on paper, mid-size), double-wall $1,200–2,400 (canvases); climate lining and a data logger add $150–450"},"freight_inter":{"n":"Freight, intercontinental","lo":1800,"hi":4500,"vf":"S","src":[["FairArt, shipping fine art: export crates, insurance (playbook)","https://fairart.com/editorial/insights/shipping-fine-art-export-crates-insurance-playbook/242"]],"note":"white-glove door to door with brokerage $1,800–4,500; airport to airport $900–2,200; a courier adds a fare and a day rate; a very large work or a sculpture costs more"},"freight_intra":{"n":"Freight, within the continent","lo":600,"hi":1500,"vf":"U","src":[["FairArt, shipping fine art: export crates, insurance (playbook)","https://fairart.com/editorial/insights/shipping-fine-art-export-crates-insurance-playbook/242"]],"note":"the playbook’s domestic door-to-door figure ($600–1,500); no intra-Europe figure was published"},"insurance":{"n":"Transit insurance","lo":0.0015,"hi":0.0045,"vf":"S","src":[["FairArt, shipping fine art: export crates, insurance (playbook)","https://fairart.com/editorial/insights/shipping-fine-art-export-crates-insurance-playbook/242"]],"note":"all-risk, nail to nail, 0.15% to 0.45% of declared value per leg, minimum $150–300"},"broker":{"n":"Customs broker","lo":120,"hi":450,"vf":"S","src":[["FairArt, shipping fine art: export crates, insurance (playbook)","https://fairart.com/editorial/insights/shipping-fine-art-export-crates-insurance-playbook/242"]],"note":"entry and clearance per shipment; temporary import bonds 0.5% to 1.5% of value pro rata"},"install":{"n":"Installation","lo":250,"hi":900,"vf":"S","src":[["FairArt, shipping fine art: export crates, insurance (playbook)","https://fairart.com/editorial/insights/shipping-fine-art-export-crates-insurance-playbook/242"]],"note":"a two-person crew with hardware"},"apostille":{"n":"Apostille","lo":20,"hi":60,"vf":"V","src":[["gov.uk, Get your document legalised (£45 standard, £35 e-Apostille)","https://www.gov.uk/get-document-legalised"],["US Department of State, Office of Authentications ($20 a document)","https://adoption.state.gov/en/replace-certify/authenticate-documents/request-services.html"]],"note":"per document: $20 at the US State Department, £45 at the FCDO, €10 at a French notary; plus the notary"},"legalisation":{"n":"Consular legalisation","lo":300,"hi":1500,"vf":"U","src":[],"note":"three stamps per document (notary, foreign ministry, embassy) and an agent; the UAE ministry’s attestation about AED 150"},"cites":{"n":"CITES permits","lo":100,"hi":600,"vf":"U","src":[["gov.uk, Declare ivory you intend to sell (pre-1918 certificate £250)","https://www.gov.uk/guidance/declare-ivory-you-intend-to-sell-or-hire-out"]],"note":"export and import permits; a UK pre-1918 ivory exemption certificate is £250 and takes about three months"},"carnet":{"n":"ATA carnet","lo":300,"hi":1200,"vf":"U","src":[["Singapore Customs, ATA carnet","https://customs.gov.sg/businesses/importing-goods/temporary-import-scheme/ata-carnet"]],"note":"the chamber of commerce’s fee plus a bond or premium on the value"},"storage":{"n":"Fine-art storage","lo":5,"hi":15,"vf":"S","src":[["Artwork Archive, the cost of shipping and storing art","https://www.artworkarchive.com/blog/cost-of-your-art-collection-shipping-and-storage"]],"note":"climate-controlled storage about $5–15 per square foot a month (undated)"}};
const NAV_MOSCOW={"q":"I have $3m in Moscow. Can it become a painting on a wall in Washington, and could the value go up on the way?","scenario":"A Russian resident with $3m in a Russian bank wishes to buy a painting in London or New York and keep it in Washington, DC.","gates":[{"n":"Moving the money out of Russia","status":"conditional","rule":"CBR counter-sanction rules let a resident transfer up to $1m (or equivalent) a month to a foreign bank account and $10,000 a month through money-transfer systems (extended 1 Oct 2025–31 Mar 2026; later six-month renewals not opened). $3m therefore takes three monthly tranches. The sending bank must still be able to reach a Western correspondent: the largest Russian banks are off SWIFT and blocked by OFAC, the EU and the UK, so the route runs through a non-sanctioned bank (U). Cash export above $10,000 is banned (Decree 81, 1 Mar 2022; U).","src":[["Pravo.ru, CBR extends limits, 26 Sep 2025","https://pravo.ru/news/260549/"],["Inc. Russia, 26 Sep 2025","https://incrussia.ru/news/bank-rossii-prodlil-na-polgoda-ogranicheniya-na-perevody-sredstv-za-rubezh/"]],"vf":"S","note":""},{"n":"Receiving the money abroad","status":"conditional","rule":"EU: Reg. 833/2014 Art. 5b bars EU banks from accepting deposits above €100,000 from Russian nationals or residents (balances aggregated per bank; interest counts), unless the person holds an EU/EEA/Swiss residence permit (Art. 5b(2)). UK: no statutory deposit cap, but a Russian resident is a person ‘connected with Russia’ and banks de-risk. US: no nationality-based deposit ban; banks screen the SDN list and the 50% rule and most refuse inbound payments from Russian banks (U). A seller’s bank in London or New York must be willing to accept the funds.","src":[["Bank of Slovenia, FAQ on financial restrictive measures (Art. 5b)","https://bsi.si/en/financial-stability/banking-system-supervision/financial-restrictive-measures/faq"],["Women Art Dealers, UK luxury goods ban (connected with Russia test)","https://womenartdealers.org/what-does-the-luxury-goods-ban-mean-for-the-art-market/"]],"vf":"S","note":""},{"n":"The house’s KYC and sanctions screening","status":"conditional","rule":"Christie’s, Sotheby’s, Phillips and Bonhams were found in 2020 to treat the agent as principal and not ask for whom he bought (Rotenberg purchases of over $18m via Highland Ventures, Steamort and Advantage Alliance; adviser Gregory Baltser). Houses now require ID, beneficial owner, source of funds and wealth, and screen buyer and payer against OFAC, UK and EU lists including entities 50% owned by listed persons (practice, U). A Russia-resident bidder paying from a Russian bank is enhanced-due-diligence at best; the big houses have declined such bidders since 2022 (U).","src":[["Senate PSI staff report, 29 Jul 2020","https://www.hsgac.senate.gov/wp-content/uploads/imo/media/doc/2020-07-29%20PSI%20Staff%20Report%20-%20The%20Art%20Industry%20and%20U.S.%20Policies%20that%20Undermine%20Sanctions.pdf"]],"vf":"S","note":""},{"n":"Luxury-goods bans: sale to a Russian resident versus shipment to Russia","status":"conditional","rule":"UK: since 14 Apr 2022 (reg. 46B, Russia (Sanctions) (EU Exit) Regulations 2019) it is prohibited to export works of art of any value (Schedule 3A, paragraph 21, carries no price threshold) to Russia or to make them available to a person ‘connected with Russia’, a test of residence or location, not nationality; a London house therefore may not sell to a Moscow resident even for delivery to Washington. US: EAR 15 CFR 746 Supp. 5 bars export or re-export of art worth $300 or more per unit to Russia or Belarus and to listed oligarchs; a sale to an unlisted Russian resident for delivery inside the US is not an export to Russia, so the EAR alone does not block it (U), though OFAC facilitation rules and bank refusals bite.","src":[["Russia (Sanctions) (EU Exit) Regulations 2019, Schedule 3A, para 21","https://www.legislation.gov.uk/uksi/2019/855/schedule/3A"],["15 CFR 746 Supplement No. 5 (mirror, checked 3 Nov 2026)","https://www.customsmobile.com/regulations/title15_chapterVII-i1_part746_appendix-i4"]],"vf":"V","note":"London route closed by the UK ‘connected with Russia’ test; New York route legally possible under the EAR for an unlisted buyer but commercially closed by KYC and banking."},{"n":"Import into the United States and tax in Washington","status":"open","rule":"Chapter 97 is duty-free; IEEPA tariffs are void (20 Feb 2026) and the 24 Jul 2026 s.301 action excludes chapter 97 (HTSUS 9903.05.86), so a UK- or US-origin painting pays no federal duty; Chinese-origin art would carry 7.5%. No CPIA restriction touches a modern painting. The District of Columbia charges a 6% use tax on tangible property brought into the District for use (rate unconfirmed, U). An FWS declaration is needed only if the frame or materials contain CITES species.","src":[["Cultural Property News, chapter 97 excluded from the 2026 s.301 action, 4 Aug 2026","https://culturalpropertynews.org/?p=16913"],["DLA Piper, Supreme Court IEEPA decision, 24 Feb 2026","https://www.dlapiper.com/insights/publications/2026/02/us-supreme-court-holds-ieepa-does-not-authorize-tariffs"]],"vf":"S","note":""},{"n":"Red flags the transaction raises","status":"closed","rule":"FinCEN’s alert of 16 Mar 2022 names artworks among the high-value assets (with real estate, precious metals, yachts, aircraft) used to evade Russia sanctions, and flags shell companies, parties associated with sanctioned Russians, and changes to art-insurance policies. The PSI report adds undisclosed principals behind an adviser. A Russia-resident buyer funding from Russia in tranches, buying through a company or adviser, or asking the house to ship to a third party would trip every one.","src":[["Covington, FinCEN alert of 16 Mar 2022","https://www.cov.com/en/news-and-insights/insights/2022/03/fincens-alert-on-aml-risk-from-evasion-of-russia-sanctions"],["Senate PSI staff report, 29 Jul 2020","https://www.hsgac.senate.gov/wp-content/uploads/imo/media/doc/2020-07-29%20PSI%20Staff%20Report%20-%20The%20Art%20Industry%20and%20U.S.%20Policies%20that%20Undermine%20Sanctions.pdf"]],"vf":"S","note":""}],"alternative":"A Russian national who is lawfully resident outside Russia (e.g. in the UAE, Switzerland or an EU state with a residence permit, which lifts the Art. 5b deposit cap), is on no sanctions list and not 50% owned by a listed person, pays from an account outside Russia whose funds were there before 2022 or are documented post-2022 income, and buys in his own name with full source-of-wealth papers. The UK ‘connected with Russia’ test and the US EAR turn on residence and destination, not passport, so he may buy in London or New York and ship to Washington; the house still runs enhanced due diligence, and DC use tax falls due.","flags":["Use of shell companies or an adviser who will not name the principal (PSI 2020: Highland Ventures, Steamort, Advantage Alliance; Gregory Baltser treated as principal by all four houses).","Involvement of persons, companies, law firms or institutions associated with sanctioned Russian individuals or companies (FinCEN alert, 16 Mar 2022).","Purchase of high-value assets, including artworks, real estate, precious metals and jewellery, yachts and aircraft, by or for sanctioned Russian parties or their proxies (FinCEN alert).","Purchase or termination of insurance policies on artwork, real estate or valuables linked to sanctioned Russian parties or their proxies (FinCEN alert).","Payment in monthly tranches that track the CBR’s $1m limit, payment from a party other than the buyer, or routing through a third-country bank newly opened for the purpose (inference from the CBR limits; house practice, U)."],"src":[["Senate PSI staff report, 29 Jul 2020","https://www.hsgac.senate.gov/wp-content/uploads/imo/media/doc/2020-07-29%20PSI%20Staff%20Report%20-%20The%20Art%20Industry%20and%20U.S.%20Policies%20that%20Undermine%20Sanctions.pdf"],["Covington, FinCEN alert of 16 Mar 2022","https://www.cov.com/en/news-and-insights/insights/2022/03/fincens-alert-on-aml-risk-from-evasion-of-russia-sanctions"],["Bank of Slovenia FAQ, Art. 5b","https://bsi.si/en/financial-stability/banking-system-supervision/financial-restrictive-measures/faq"],["15 CFR 746 Supplement No. 5 (mirror)","https://www.customsmobile.com/regulations/title15_chapterVII-i1_part746_appendix-i4"],["Women Art Dealers, UK luxury goods ban","https://womenartdealers.org/what-does-the-luxury-goods-ban-mean-for-the-art-market/"],["Pravo.ru, CBR limits, 26 Sep 2025","https://pravo.ru/news/260549/"]]};
